WITH payload AS (SELECT $archive_payload$[{"id":"56086712-f44f-5d5e-ab84-bc389f0b2503","document_type":"judgment","category":"judicial","subcategory":"general","title":"أتعاب محاماة -انتحال صفة احملامي -عدم صحة كون املدعي محام -الوكيل إذا ترافع يف اخلصومة ولم يكن محامي ا نظامي ا فإنه يستحق أجرة املثل -تقدير أجل املثل عن طريق أهل اخلبرة- الغش والتدليس محرم يف الشريعة ثبوت تدليس وغش املدعي- احلكم له بأجرة املثل صرف النظر عن مطالبته مبا ذكر يف العقد -بعث أوراق املدعى جلهة االختصاص للتحقيق معه ومعاقبته النتحاله مهنة ال يتقنها ولم يرخص له.","document_number":"33408025","case_number":"14510","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام وقد وردتنا املعاملة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/9/11","year":"1434","subject":"أتعاب محاماة -انتحال صفة احملامي -عدم صحة كون املدعي محام -الوكيل إذا ترافع يف اخلصومة ولم يكن محامي ا نظامي ا فإنه يستحق أجرة املثل -تقدير أجل املثل عن طريق أهل اخلبرة- الغش والتدليس محرم يف الشريعة ثبوت تدليس وغش املدعي- احلكم له بأجرة املثل صرف النظر عن مطالبته مبا ذكر يف العقد -بعث أوراق املدعى جلهة االختصاص للتحقيق معه ومعاقبته النتحاله مهنة ال يتقنها ولم يرخص له.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33408025 :‬تاريخه ‪1433/9/11 :‬هـ‬\n                             ‫رقم الدعوى ‪14510 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3441754‬تاريخه‪1434/2/19 :‬هـ‬\n\n\n       ‫أتعــاب محامــاة ‪ -‬انتحــال صفــة احملامــي ‪ -‬عــدم صحــة كــون املدعــي‬\n       ‫محــام ‪ -‬الوكيــل إذا ترافــع يف اخلصومــة ولــم يكــن محاميـ ًا نظاميـ ًا‬\n       ‫فإنــه يســتحق أجــرة املثــل ‪ -‬تقديــر أجــل املثــل عــن طريــق أهــل اخلبــرة‪-‬‬\n       ‫الغــش والتدليــس محــرم يف الشــريعة ـ ثبــوت تدليــس وغــش املدعــي‪-‬‬\n       ‫احلكــم لــه بأجــرة املثــل ـ صــرف النظــر عــن مطالبتــه مبــا ذكــر يف‬\n       ‫العقــد ‪ -‬بعــث أوراق املدعــى جلهــة االختصــاص للتحقيــق معــه‬\n                        ‫ومعاقبتــه النتحالــه مهنــة ال يتقنهــا ولــم يرخــص لــه‪.‬‬\n\n\n\n       ‫‪ .1‬اتفــق أهــل العلــم علــى حرمــة الغــش ســواء كان بالقــول ‪ ،‬أو‬\n       ‫الفعــل‪ ،‬وســواء كان بكتمــان العيــب يف املعقــود عليــه أو الثمــن أو‬\n       ‫بالكــذب واخلديعــة‪ ،‬ســواء أكان يف املعامــات أو يف غيرهــا مــن املشــورة‬\n       ‫والنصيحــة ‪ .‬قــال الترمــذي رحمــه اهلل ـ كمــا يف الســن مــا نصــه ‪:‬‬\n                ‫«والعمــل علــى هــذا عنــد أهــل العلــم وقالــوا ‪ :‬الغــش حــرام»‪.‬‬\n       ‫‪ .2‬جــاء يف الصحيحــن مــن حديــث أبــي هريــرة ـ رضــي اهلل عنــه ـ أن‬\n       ‫رســول اهلل صلــى اهلل عليــه وســلم قــال ( ال تصــروا اإلبــل والغنــم فمــن‬\n       ‫ابتاعهــا بعــد ذلــك فهــو بخيــر النظريــن بعــد أن يحلبهــا إن رضيــا‬\n                                ‫أمســكها وإن ســخطها ردهــا وصاعــا مــن متــر )‪.‬‬\n       ‫‪ .3‬قــال املــردواي يف اإلنصــاف ( ‪ « ) 394/6‬تنبيــه ‪ :‬مــراد املصنــف وغيــره‬\n       ‫ا بغيــر جعــل فــا شــيء لــه ) غيــر‬  ‫بقولهــم ( ومــن عمــل لغيــره عم ـ ً‬\n‫‪241‬‬\n\f‫املعــد ألخــذ األجــرة ‪ ،‬فأمــا املعــد ألخذهــا فلــه األجــرة قطعـ ًا كاملــاح ‪،‬‬\n‫واملــكاري ‪ ،‬واحلجــام ‪ ،‬والقصــار ‪ ،‬واخليــاط ‪ ،‬والــدالل ‪ ،‬ونحوهــم ممــن‬\n‫يرصــد نفســه للتكســب بالعمــل ‪ ،‬فــإذا عمــل ‪ :‬اســتحق أجــرة املثــل ‪ ،‬نــص‬\n                                                                          ‫عليــه»‬\n‫‪ .4‬وقــال العالمــة البهوتــي ـ رحمــه اهلل ـ يف كشــاف القنــاع كتــاب‬\n‫ا بغيــر جعــل فال شــيء له )‬‫اجلعالــة ( ‪( « ) 485/9‬ومــن عمــل لغيــره عمـ ً‬\n‫ألنــه بــذل منفعتــه مــن غيــر عــوض فلــم يســتحقه ‪ ،‬ولئــا يلــزم اإلنســان‬\n‫مــا لــم يلتزمــه ‪ ،‬ولــم تطــب نفســه بــه ‪ ،‬إن لــم يكــن العامــل معــدا ألخــذ‬\n‫األجــرة ‪ ،‬فــإن كان معــد ًا لذلــك كاملــاح واملــكاري واحلجــام والقصــار‬\n‫واخليــاط والــدالل ونحوهــم كالنقــاد والكيــال والــوزان وشــبههم ممــن‬\n‫يرصــد نفســه للتكســب بالعمــل وأذن لــه املعمــول لــه يف العمــل فلــه‬\n     ‫أجــرة املثــل لداللــة العــرف علــى ذلــك ‪ ،‬وتقــدم معنــاه يف اإلجــارة»‬\n‫ا‬\n‫‪ .5‬املــادة ( ‪ )1/17‬مــن نظــام احملامــاة ‪ ( :‬يكــون الشــخص منتح ـ ً‬\n‫صفــة احملامــي إذا قــام بعمــل يجعــل لــه صفــة احملامــي ‪ ،‬ومــن ذلــك‬\n‫فتــح مكتــب إلســتقبال قضايــا الترافــع واالستشــارات ‪ ،‬أو اإلشــارة يف‬\n                                 ‫مطبوعــات إلــى نفســه بصفــة احملامــي )‬\n\n\n\n\n‫ادعــى املدعــي بأنــه اتفــق مــع املدعــى عليــه علــى متابعــة قضايــاه وتقدميها‬\n‫إلــى احملاكــم الشــرعية وبعدمــا عمــل مــع املدعــى عليه وقام بتقدمي ســت‬\n‫قضايــا لــه يف ديــوان املظالــم علــى أن يكــون لــه ‪ % 10‬مــن قيمــة القضايــا‬\n‫‪ -‬قــام املدعــى عليــه بفســخ وكالتــه ‪ -‬ويطلــب املدعــي مــن املدعــى عليــه‬\n‫مــا قــام بــه مــن أعمــال تقديــر قيمتهــا ب ـ ‪ 443,295‬ـ صــادق املدعى عليه‬\n\n                                                                                      ‫‪242‬‬\n\f      ‫علــى مــا ذكــره املدعــي مــن أنــه قــام بالترافــع عنــه وتقــدمي قضايــاه إلــى‬\n      ‫ديــوان املظالــم لكــن اتفاقــه مــع املدعــي علــى أســاس كونــه محامي ـ ًا‬\n      ‫واتضــح أن املدعــي معقــب وليــس محاميـ ًا وبالتالــي يصبــح العقــد باطــل‬\n      ‫لثبــوت غــش املدعــي ـ ذكــر املدعــى عليــه أن القضايــا التــي قــام املدعــي‬\n      ‫بتقدميهــا قــد صــرف النظــر عنهــا لعــدم االختصــاص وحولــت بعضهــا‬\n      ‫إلــى جلنــة التحكيــم ‪ ،‬بــل طلــب صحيفــة الدعــوى ولــم يكتبهــا ولــم‬\n      ‫يذهــب بهــا إلــى الديــوان حتــى تســبب يف تأجيــل القضيــة ألكثــر مــن‬\n      ‫ا ألحــد أخصــام املدعــى عليــه ـ بعــرض‬      ‫شــهر كمــا أن املدعــي وكي ـ ً‬\n      ‫هــذا اجلــواب علــى املدعــي أنكــر مــا جــاء فيــه ســوى مــا ذكــره مــن أنــه‬\n      ‫لــم يحضــر صحيفــة الدعــوى حيــث صحيفــة الدعــوى مرفقــة باملعاملــة‬\n      ‫ال‬‫وجــرى تأجيــل اجللســة بنــاء علــى رغبــة املدعــى عليه ‪ ،‬أمــا كونه وكي ً‬\n      ‫ا لــه‬ ‫ألحــد أخصــام املدعــى عليــه فهــذا غيــر صحيــح حيــث كان وكيـ ً‬\n      ‫ضــد إحــدى الدوائــر احلكوميــة قبــل خمســة عشــر عامـ ًا ـ ذكــر املدعــى‬\n                   ‫عليــه أنــه اتفــق مــع املدعــي أنــه محــام واحضــر شــاهد ًا لذلــك‪.‬‬\n      ‫أبــرز املدعــى عليــه خطاب ـ ًا موجهــا مــن مؤسســته إلــى مكتــب املدعــي‬\n      ‫موصــوف بكونــه مكتــب استشــارات قانونيــة وبعــرض ذلــك علــى‬\n      ‫املدعــي قــال أطلــب مهلــة للجــواب هــل وصلــه أم ال ‪ ،‬ويف جلســة أخــرى‬\n      ‫أقــر بوصولــه إليــه ـ جــرت الكتابــة إلــى ديــوان املظالــم للتأكــد مــن‬\n      ‫اجللســات التــي قدمــت باســم املدعــى عليــه فــورد اجلــواب مــن ديــوان‬\n      ‫املظالــم بــأن املدعــي م َّثــل املدعــى عليــه يف أربــع قضايــا مشــتملة كل‬\n      ‫معاملــة علــى الئحــة دعــوى مكونــة مــن ورقــة واحــدة ومــع كل الئحــة‬\n      ‫عــدد مــن املرفقــات ‪ -‬كمــا أفــاد اخلطــاب بــأن الوكيــل قــد حضــر‬\n      ‫اجللســة األولــى للقضيتــن ولــم يحضــر يف جلســات املعاملتــن األخريتــن‬\n\n\n‫‪243‬‬\n\f‫‪ -‬جــرت الكتابــة لفــرع الديــوان لإلفــادة عــن الدعــاوى التــي تقــدم بهــا‬\n‫ا عــن املدعــى عليــه فــورد اجلــواب أن املدعــى م َّثــل املدعــى‬\n                                                                   ‫املدعــي وكيـ ً‬\n‫عليــه يف جلســة واحــدة انتهــت باحلكــم بعــدم اختصــاص الديــوان‬\n‫والئي ـ ًا بنظــر الدعــوى وقــد صــدق احلكــم مــن هيئــة التدقيــق ‪ -‬جــرت‬\n‫الكتابــة لهيئــة النظــر لتقديــر مــا يســتحقه املدعــي نظيــر أعمالــه التــي‬\n‫عملهــا للمدعــى عليــه فقامــت بالكتابــة للغرفــة التجاريــة فــورد جــواب‬\n‫جلنــة احملامــن تتضمــن أن املدعــي يســتحق مبلــغ وقــدره أربعــون ألــف‬\n‫ريــال لقــاء أعمالــه التــي قــام بهــا للمدعــى عليــه ـ فجــرى االطــاع علــى‬\n‫االتفاقيــة بــن املدعــي واملدعــى عليــه واملعنونــة (‪ )......‬وبســؤال املدعــي‬\n‫عــن اختــاف رقــم الســجل مــع املطبوعــات اســتعد بإحضــار أصــل‬\n‫الســجل التجــاري ـ يف جلســة أخــرى أبــرز شــهادة شــطب الصــادرة مــن‬\n‫فــرع وزارة التجاريــة ملؤسســة املدعــي وســبب الشــطب انتقــال املؤسســة‬\n‫مــن الدمــام إلــى اخلبــر ـ متــت الكتابــة لفــرع وزارة التجــارة والصناعــة‬\n‫للتأكــد مــن تاريــخ الســجل التجــاري ونشــاط الســجل التجــاري ‪ -‬فــورد‬\n‫اجلــواب أن تاريــخ الســجل التجــاري هــو ‪1418/9/21‬ه ـ ‪ -‬وأن نشــاطه‬\n‫مقــاوالت عامــة للمبانــي وإنشــاء وإصــاح وترميــم ـ متــت الكتابــة لفــرع‬\n‫وزارة التجــارة والصناعــة حيــال هــذا االختــاف فــورد اجلــواب أن نشــاط‬\n‫ســجل املدعــي ملزاولــة نشــاط حتصيــل الديــون نيابــة عــن الغيــر ‪ -‬مت‬\n‫الطلــب مــن املدعــي صــور لألحــكام التــي قــام بحضــور جلســاتها لــدى‬\n‫ديــوان املظالــم فقــدم صــورة صكــن ‪ -‬قــدرت أجــرة املثــل للمدعــي‬\n‫أربعــون ألــف ريــال ـ دلــت األدلــة علــى حتــرمي الغــش يف الشــريعة ‪ -‬الغــش‬\n‫يشــمل كل األنــواع يف األمــوال واملعامــات واألقــوال ـ النظــام نــص‬\n‫علــى مــن فتــح مكتــب لالستشــارات والترافــع يكــون قــد انتحــل‬\n\n\n                                                                                     ‫‪244‬‬\n\f      ‫صفــة احملامــي ـ ثبــوت تدليــس املدعــي بانتحالــه مهنــة ال يتقنهــا ـ احلكــم‬\n      ‫للمدعــي بأجــرة املثــل وهــو مبلــغ أربعــن ألــف ريــال ـ بالنســبة النتحــال‬\n      ‫املدعــي مهنــة ال يتقنهــا ولــم يرخــص لهــا فيهــا فســيتم بعــث أوراقــه جلهــة‬\n      ‫االختصــاص للتحقيــق معــه حســب املــادة (‪ ) 37‬مــن نظــام احملامــاة ـ قــرر‬\n      ‫املدعــي واملدعــى عليــه عــدم قناعتهمــا باحلكــم بلوائــح اعتراضيــة ـ‬\n                                        ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا (‪ )...‬القاضــي باحملكمــة العامــة بالدمام‬\n      ‫وقــد وردتنــا املعاملــة مــن فضيلــة الرئيــس املقيــدة لدينــا برقــم ‪14510‬يف‬\n      ‫‪1428‬ه ـ يف دعــوى ‪...‬ضــد ‪ ...‬افتتحــت اجللســة ويف هــذه اجللســة حضــر‬\n      ‫املدعــي ‪...‬احلامــل للبطاقــة رقــم ‪...‬رقــم احلفيظــة ‪...‬الصــادرة مــن ظهــران‬\n      ‫اجلنــوب يف ‪1386/4/13‬ه ـ وحضــر حلضــوره ‪...‬مصــري اجلنســية رخصــة‬\n      ‫اإلقامــة رقــم ‪...‬يف ‪1423/6/2‬ه ـ الصــادرة مــن هيئــة االســتثمار بالدمــام‬\n      ‫وادعــى قائــا‪ :‬بأننــي اتفقــت مــع املدعــى عليــه مبوجــب عقــد علــى متابعة‬\n      ‫قضايــاه وتقدميهــا إلــى احملاكــم الشــرعية وبعــد مــا عملــت مــع املذكور‬\n      ‫وقمــت لــه بتقــدمي ســت قضايــا خمــس منهــا يف ديــوان املظالــم بالدمــام‬\n      ‫وواحــدة منهــا يف ديــوان املظالــم باملدينــة املنــورة علــى أن يكــون لــي‬\n      ‫عشــرة ‪ % 10‬مــن قيمــة القضايــا‪ ،‬ويف ‪1426/3/27‬ه ـ قــام املذكــور‬\n      ‫بإرســال خطــاب لــي علــى الفاكــس بفســخ وكالتــي وحيــث أننــي قمــت‬\n      ‫بالعمــل والعقــد ينــص أن لــي حــق املطالبــة باألتعــاب لــو مت فســخ العقــد‬\n      ‫وأنــا أســتحق عليــه مبلــغ أربعمائــة وثالثــة وأربعــون ألــف ومئتــان وتســعة‬\n\n‫‪245‬‬\n\f‫وخمســون ريــال حســب املــادة اخلامســة مــن العقــد اطلــب إلزامــه بدفــع‬\n‫املبلــغ‪ ،‬وبعــرض الدعــوى علــى املدعــى عليــه أجــاب قائــا‪ :‬بأننــي اتفقــت‬\n‫مــع املدعــي مبوجــب عقــد علــى انــه محامــي وقــد اتضح لي بــأن املذكور‬\n‫معقــب وليــس محامــي وأن العقــد معــه باطــل لثبــوت غــش املدعــي لنــا يف‬\n‫بــادئ األمــر بإخفــاء طبيعــة عملــه وادعــاءه بأنــه محامــي وبعدمــا علمــت‬\n‫أنــه ليــس محامــي أخبرتــه بذلــك وقــال لــي‪ :‬ايــه الفــرق بينــي وبــن‬\n‫احملامــي علــى األقــل أنــا احضــر معــاك اجللســات واحملامــي يرســل‬\n‫منــدوب ثانيــا مت االتفــاق معــه علــى أتعــاب القضايــا بنســبة ‪ %10‬بعــد‬\n‫التحصيــل فقــط والتــي لــم حتصــل إلــى اآلن بســبب جهلــه بالقضايــا‬\n‫والتــي صــرف عنهــا النظــر بعــدم االختصــاص والقبــول وحولــت إلــى جلنــة‬\n‫التحكيــم واملدعــي لــم يظهــر إال أول جلســة والتــي اف ُتضــح أمــره فيهــا‬\n‫حيــث طلبــت منــه صحيفــة الدعــوى ووعدنــي بإحضارهــا صبــاح يــوم‬\n‫اجللســة وحينمــا حضــرت قــال لــي‪ :‬أن ســكرتير دائــرة الديــوان يقــول ال‬\n‫حاجــة لصحيفــة الدعــوى يف اجللســة األولــى وبعــد املثــول أمــام القضــاة‬\n‫طلــب منــي صحيفــة الدعــوى فلــم اســتطع اإلجابــة وســأل ‪...‬وقــال أننــي‬\n‫لــم أعمــل صحيفــة الدعــوى وجــرى تأجيــل اجللســة ألكثــر مــن شــهر‬\n‫وبعــد ذلــك طلبــت منــه صحيفــة الدعــوى فقــدم لــي دعــوى مكتوبــة‬\n‫بخــط اليــد مكــررة الــكالم يذكــره يف الئحــة الدعــوى التــي أعدهــا‬\n‫ســابقا وثبــت غــش املدعــي وعــدم التزامــه بالعقــد وعــدم قدرتــه علــى‬\n‫العمــل يف مثــل هــذه القضايــا واســتوجب علينــا إلغــاء الوكالــة واملدعــي‬\n‫يحــاول ابتــزازي باألمــوال ســابقا وحاليــا وبــدون وجــه حــق كمــا أننــي‬\n‫ســمعت أن املدعــي وكيــا خلصمــي يف أحــد القضايــا لــدى ديــوان‬\n‫املظالــم وأطلــب هــذه الدعــوى لعــدم اســتحقاق مــا يدعيــه‪ ،‬ويف اجللســة‬\n\n\n                                                                                  ‫‪246‬‬\n\f      ‫التــي تليهــا حضــر الطرفــان وبعــرض مــا جــاء يف إجابــة املدعــى عليــه‬\n      ‫علــى املدعــي أجــاب قائــا‪ :‬بــأن مــا ذكــره املدعــى عليــه مــن أنــه اتفــق‬\n      ‫معــي علــى أننــي محامــي فهــذا غيــر صحيــح ومــا ذكــره أيضــا مــن انــه‬\n      ‫لــم يعلــم أننــي غيــر محامــي قلــت لــه‪ :‬ايــه يفــرق بينــي وبــن احملامــي علــى‬\n      ‫األقــل أنــا أحضــر معــك اجللســات واحملامــي يرســل منــدوب فهــذا غيــر‬\n      ‫صحيــح ومــا ذكــره أن الدعــاوى التــي قدمتهــا ُصــرف نظــر عنهــا بعــدم‬\n      ‫االختصــاص وحولــت إلــى جلنــة التحكيــم فهــذا غيــر صحيــح وما ذكره‬\n      ‫املدعــى عليــه مــن أننــي لــم أحضــر صحيفــة الدعــوى يف اجللســة األولــى‬\n      ‫يف ديــوان املظالــم فهــذا غيــر صحيــح بــل صحيفــة الدعــوى مرفقــة‬\n      ‫باملعاملــة وأجلــت اجللســة األولــى وذلــك حســب طلــب املدعــى عليــه وذلــك‬\n      ‫إلحضــار البينــة علــى نفــي الدعــوى ومــا ذكــره املدعــى عليــه مــن إننــي‬\n      ‫كنــت وكيــا ل‪ ... ...‬يف أحــد القضايــا يف ديــوان املظالــم فهــذا غيــر‬\n      ‫صحيــح حيــث كنــت وكيــا لــه يف دعــوى ضــد‪ )...( /‬وذلــك قبــل‬\n      ‫خمســة عشــر ســنة‪ ،‬وســمع ذلــك املدعــى عليــه وقــال‪ :‬الصحيــح مــا‬\n      ‫ذكرتــه ولــدي البينــة علــى أننــي اتفقــت معــه أنــه محامــي واســتعد‬\n      ‫بإحضارهــا‪ ،‬ويف اجللســة التــي تليهــا قــال املدعــى عليــه لــدي اخلطــاب‬\n      ‫املوجــه للمدعــي وقــد ذكــرت يف خطابــي أنــه محامــي ولــم ينفــي ذلــك‬\n      ‫وقــد أرســلت لــه اخلطــاب بالفاكــس واطلــب إمهالــي إلحضــار األصــل‪،‬‬\n      ‫ويف جلســة أخــرى طلــب مــن املدعــى عليــه البينــة فأحضــر ‪...‬احلامــل‬\n      ‫للبطاقــة ‪...‬رقــم احلفيظــة ‪...‬يف ‪1396/1/11‬ه ـ الصــادرة مــن االحســاء‬\n      ‫مــن مواليــد عــام ‪ 1376‬صاحــب مؤسســة خاصــة وال يوجــد بينــه وبــن‬\n      ‫الطرفــن صلــة قرابــة وهــو صديــق للمدعــى عليــه وشــهد قائــا أشــهد‬\n      ‫بــأن صديقــي املدعــى عليــه ‪...‬طلــب منــي تنظيم مؤسســته وأثنــاء تنظيمي‬\n\n\n‫‪247‬‬\n\f‫لعملــه طلــب منــي أن ابحــث لــه عــن محامــي وكان يراجعنــا منــدوب‬\n‫‪...‬املدعــو ‪ ...‬وطلبــت منــه ان يرشــدني إلــى محامــي وأعطانــي هاتــف‬\n‫شــخص واتصلــت عليــه وقلــت لــه‪ :‬إننــا بحاجــة إلــى محامــي وســألته عــن‬\n‫مكتبــه وقــال‪ :‬انــه ال يوجــد لــي مكتــب ثابــت وأنــا أحضــر إليكــم ثــم‬\n‫حضــر لــي يف املكتــب فحضــر إلــى املكتــب فعرفنــي بنفســه انــه ‪...‬‬\n‫وقمــت بإدخالــه إلــى املدعــى عليــه وال اعلــم مــا بينهمــا مــن اتفــاق هــذا مــا‬\n‫لــدي كمــا أبــرز املدعــى عليــه خطــاب معنــون مؤسســة (‪ )...‬للمقــاوالت‬\n‫والديكــور برقــم ‪/43‬م م ‪/‬ص ‪ 2005/‬التاريــخ ‪ 2005/4/12‬الســادة‬\n‫مكتــب (‪ )...‬عنايــة األســتاذ‪ )...(/‬احملامــي احملتــرم الســام عليكــم‬\n‫ورحمــة اهلل وبركاتــه وبعــد إحلاقــا بالعقــود املســلمة مــن طرفنــا واملعــدة‬\n‫بيننــا وبــن مؤسســة (‪ )...‬اخلاصــة مبشــروع فنــدق (‪ ..)...‬الــخ وبعــرض‬\n‫ذلــك علــى املدعــي أجــاب قائــا‪ :‬بأننــي ال اعلــم هــل هذا اخلطــاب وصلني‬\n‫أو ال وأطلــب إعطائــي صــورة منــه حتــى أمتكــن مــن التأكــد منــه‪ ،‬ويف‬\n‫اجللســة التــي تليهــا حضــر الطرفــان وبســؤال املدعــي عــن مــا طلــب‬\n‫اإلمهــال لــه أجــاب قائــا‪ :‬إن اخلطــاب الــذي قدمــه املدعــى عليــه برقــم‬\n‫‪/43‬م م ‪/‬ص ‪ 2005/‬وتاريــخ ‪ 2005/4/12‬قــد وصــل لــي وحيــث أن‬\n‫الدعــاوي التــي وكل بهــا املدعــى عليــه املدعــي قــد نظــرت يف ديــوان‬\n‫املظالــم باملنطقــة الشــرقية واملدينــة املنــورة وأضــاف املدعــي بــأن‬\n‫الدعــاوى لــدى ديــوان املظالــم باملنطقــة الشــرقية الدائــرة اخلامســة عشــر‬\n‫والدائــرة السادســة عشــر التــي يف املدينــة املنــورة لــدى الدائــرة احلاديــة‬\n‫والعشــرون والدعــوى مقامــة ضــد املكتــب االستشــاري املســمى ‪.. .‬‬\n‫ورفعــت اجللســة للكتابــة لديــوان املظالــم باملنطقــة الشــرقية وديــوان‬\n‫املظالــم باملدينــة املنــورة بطلــب اإلفــادة عمــا لديهــم ومــن حضــر اجللســات‬\n\n\n                                                                                          ‫‪248‬‬\n\f      ‫ومــا مت بهــا‪ ،‬ويف هــذه اجللســة حضــر الطرفــان وقــد جــرى الكتابــة‬\n      ‫لديــوان املظالــم باملنطقــة الشــرقية باخلطــاب رقــم ‪ 28/16631‬يف‬\n      ‫‪1428/7/14‬ه ـ وذلــك لطلــب اإلفــادة عــن القضايــا التــي حضرهــا‬\n      ‫املدعــي وقــد أعيــدت لنــا األوراق مــن فضيلــة الرئيــس برقــم ‪ 14510/‬يف‬\n      ‫‪1428/8/22‬ه ـ شــرحا علــى خطــاب فضيلــة رئيــس فــرع ديــوان املظالــم‬\n      ‫باملنطقــة الشــرقية بالنيابــة رقــم ‪/‬د‪/‬ت‪/‬ج‪ 3/3752/287/15/‬يف‬\n      ‫‪1428/8/21‬ه ـ واملتضمــن بعــد املقدمــة (نفيدكــم أن املدعــو ‪.../‬تقــدم‬\n      ‫بالوكالــة عــن املدعــو ‪... /‬بأربــع لوائــح دعــوى كال منهــا مــن ورقــة‬\n      ‫واحــدة ومــع كل الئحــة عــدد مــن املرفقــات وجــرى تعديــل كل منهــا‬\n      ‫قضيــة مســتقلة وهــي القضايــا رقــم (‪ )...‬ورقــم (‪ )...‬ورقــم (‪ )...‬ورقــم (‪)...‬‬\n      ‫وذلــك للعــام ‪1425‬ه ـ وحضــر الوكيــل فقــط يف اجللســة األولــى فقــط‬\n      ‫للقضيتــن رقــم (‪ )...‬ورقــم (‪ )...‬ولــم يحضــر يف جلســات القضيتــن‬\n      ‫األخيرتــن أ‪.‬هــ)‪ ،‬ويف هــذه اجللســة حضــر املدعــي ولــم يحضــر املدعــى‬\n      ‫عليــه وقــد جــرت الكتابــة لفضيلــة رئيــس ديــوان املظالــم باملدينــة املنــورة‬\n      ‫باخلطــاب رقــم ‪ 29/556‬يف ‪1429/1/7‬ه ـ بطلــب اإلفــادة عــن القضايــا‬\n      ‫التــي لديهــم ومــاذا قــام بــه املدعــي ‪...‬وقــد أعيــدت لنــا األوراق مــن فضيلــة‬\n      ‫الرئيــس برقــم ‪ 29/2133‬يف ‪1429/1/24‬ه ـ شــرحا علــى خطــاب‬\n      ‫فضيلــة رئيــس فــرع ديــوان املظالــم مبنطقــة املدينــة املنــورة رقــم‬\n      ‫‪/1/22/269‬د‪/‬جت‪ 21/‬يف ‪1429/1/14‬ه ـ واملتضمــن مــا نصــه بعــد‬\n      ‫املقدمــة (نفيدكــم أن املدعــو ‪...‬تقــدم بدعــوى ســجلت لــدى الديــوان‬\n      ‫برقــم ‪/5/22/1‬ق لعــام ‪1426‬ه ـ وكالــة عــن ‪...‬ضــد مكتــب املهنــدس‬\n      ‫‪...‬وقــد وردت للفــرع بتاريــخ ‪1426/1/3‬ه ـ وحكــم بهــا بتاريــخ‬\n      ‫‪1426/1/9‬ه ـ باحلكــم املرفــق رقــم ‪/55‬ت ج‪ 21/‬لعــام ‪1426‬ه ـ بعــدم‬\n\n\n‫‪249‬‬\n\f‫اختصــاص ديــوان املظالــم والئيــا بنظــر الدعــوى وقــد حضــر جلســة‬\n‫احلكــم املدعــي أصالــة وأيــد احلكــم مــن هيئــة التدقيــق حلكمهــا رقــم‬\n‫‪/314‬ت‪/‬ت لعــام ‪1426‬ه ـ أ‪.‬ه ـ وحضــر املدعــى عليــه متأخــرا أثنــاء‬\n‫اجللســة لــذا فقــد رفعــت اجللســة وذلــك للكتابــة لهيئــة النظــر لتقديــر مــا‬\n‫يســتحقه املدعــي مــن أتعــاب‪ ،‬ويف هــذه اجللســة حضــر املدعــي ولــم‬\n‫يحضــر املدعــى عليــه أو وكيلــه وقــد أعيــدت لنــا األوراق مــن رئيــس‬\n‫هيئــة النظــر برقــم ‪ 29/7060‬يف ‪1429/9/14‬ه ـ املرفــق باملعاملــة قــرار‬\n‫هيئــة النظــر رقــم ‪274‬يف ‪ 1429/9/13‬املتضمــن انــه جــرت الكتابــة‬\n‫مــن هيئــة النظــر للغرفــة التجاريــة ومت الــرد من الغرفــة التجارية باخلطاب‬\n‫املرفــق باملعاملــة وتــرى هيئــة النظــر بــأن مــا مت مــن قــرار مــن الغرفــة‬\n‫التجاريــة يكــون ملزمــا للطرفــن ألنهــا جهــة اختصــاص مبثــل هــذه‬\n‫األمــور وبالرجــوع للمعاملــة وجــد خطــاب غرفــة الشــرقية رقــم‬\n‫‪ 34300/99/1740‬يف ‪2008/7/5‬م املوافــق ‪1429/7/2‬ه ـ املوجــه‬\n‫لفضيلــة الشــيخ ‪...‬رئيــس محاكــم املنطقــة الشــرقية املكلــف املتضمــن‬\n‫بعــد املقدمــة انــه مت عــرض املوضــوع علــى جلنــة احملامــن التــي تــرى بعــد‬\n‫دراســة القضيــة مــا يلــي‪ :‬أوال ‪/‬يف حالــة ثبــوت أن الســيد‪.../‬قدم نفســه‬\n‫علــى انــه محامــي متخصــص ومت التعاقــد معــه علــى هــذه الصفــة ولــم‬\n‫يعلــم الســيد‪ ... /‬بحقيقــة األمــر إال بعــد البــدء يف الترافــع مــن قبــل الســيد‬\n‫‪ ،...‬فإننــا نكــون بصــدد خطــأ يف الشــخص املتعاقــد معــه أو مــا يســمى‬\n‫الغلــط يف أهليــة الوكيــل املهنيــة ومــن ثــم فــإن العقــد باطــل‪ ،‬ثانيــا‪ :‬يف‬\n‫حالــة عــدم ثبــوت مــا ذكــر يف أوال فــإن العقــد صحيــح ويكــون الســيد‬\n‫‪ ...‬قــدم نفســه وكيــا ولــه تلــك الصفــة مبوجــب نظــام احملامــاة املــادة‬\n‫‪/18‬أ ولكــن الوكيــل ال يســتحق مثــل أجــر احملامــي املتخصــص‬\n\n\n                                                                                         ‫‪250‬‬\n\f      ‫املســئول إمــام عمليــة مســؤولية مهنيــة وعقديــة وإمنــا يســتحق أجــر املثــل‬\n      ‫يف حالــة عــدم مخالفــة نصــوص العقــد املبــرم بينــه وبــن موكلــه وإثباتــه‬\n      ‫لســاعات العمــل التــي قضاهــا ونوعيــة اجلهــد املبــذول‪ ،‬ثالثــا‪ :‬يتضــح مــن‬\n      ‫أوراق القضيــة مــا يلــي‪/1 :‬الســيد‪... /‬لــم يوضــح عــدد ســاعات العمــل‬\n      ‫التــي قضاهــا علــى هــذه القضايــا ومــا هــو نــوع اجلهــد املبــذول ‪/2‬انــه‬\n      ‫خالــف نصــوص االتفــاق املبــرم بينــه وبــن موكلــه عنــد طلبــه مبلــغ‬\n      ‫ثالثــون الــف ريــال ‪/3‬إن نطــاق عملــه املطالــب باألتعــاب عنــه كان ثــاث‬\n      ‫مســؤوليات املرافعــة والتعقيــب والتحصيــل وهــو لــم يباشــر إال واحــدة‬\n      ‫فقــط وملــدة قصيــرة ومــرات محــدودة ‪ /4‬إن املذكــرات املقدمــة مــن‬\n      ‫قبلــه لــم تعكــس بأنــه متمــرس يف املرافعــات ويف عمليــة توظيــف األدلــة‬\n      ‫وإمنــا نقــل البيانــات نقــا عــن موكلــه وذيــل ذلــك بالطلــب مــن احملكمــة‬\n      ‫احلكــم لصالــح موكلــه‪ ،‬وعليــه فــإن جلنــة احملامــن تــرى بــأن املدعــي ‪...‬‬\n      ‫يســتحق مبلــغ وقــدره أربعــون ألــف ريــال لقــاء جهــده يف نقــل البيانــات مــن‬\n      ‫ملفــات موكلــه إلــى الئحــة الدعــوى وتكاليــف الســفر أ‪.‬هــ‪ ،‬ويف جلســة‬\n      ‫أخــرى حضــر الطرفــان وبتالوتــه علــى الطرفــن أجــاب املدعــي‪ :‬بــأن‬\n      ‫املدعــى عليــه اتصــل بــي وحضــرت عنــده وطلــب منــي الترافــع يف هــذه‬\n      ‫القضايــا ولــم أقــدم نفســي بأننــي محامــي‪ ،‬وســمع ذلــك املدعــى عليــه‬\n      ‫وقــال‪ :‬إن جميــع مخاطباتــي لــه أخاطبــه بصفــة احملامــي وجميــع وثائقــه‬\n      ‫التــي قدمهــا لــي معنونــة باســم مكتــب ‪...‬لالستشــارات القانونيــة‬\n      ‫وحتصيــل الديــون ســجل جتــاري رقــم (‪ )...‬وأنــا لــم اعلــم انــه ليس محامي‬\n      ‫إال بعــد اجللســة األولــى يف الديــوان لــدى الدائــرة السادســة عشــر وعندمــا‬\n      ‫طلــب منــه مذكــرة الدعــوى لــم يقدمهــا وأجلــت اجللســة لتقــدمي مذكــرة‬\n      ‫الدعــوى وعنــد خروجــي طلــب منــي القاضــي الرجــوع واخبرنــي بــأن‬\n\n\n‫‪251‬‬\n\f‫قضايــا كبيــرة حتتــاج إلــى محامــي فقلــت‪ :‬أنــا الــذي معــي محامــي‬\n‫فأخبرنــي أنــه ليــس محامــي وإمنــا هــو معقــب ولــه املرافعــة يف ثــاث‬\n‫قضايــا وهــو وكيــل ل‪...‬املدعــى عليــه مــن قبلــي وقــد أصبــح وكيــا‬\n‫خلصمــي أيضــا وأنــا لــم أعــرف بذلــك وطلبــت منــه أن يحضــر أو يرشــح‬\n‫شــخص محامــي ويتعــاون معــه؛ وألنــه رفــض ذلــك وســمع ذلــك املدعــي‬\n‫وقــال‪ :‬أنــا أترافــع يوميــا يف الديــوان مبعــدل مــن خمــس إلــى عشــر‬\n‫جلســات شــهريا ويف الدعــاوى اخلاصــة باملدعــى عليــه قدمــت إلــى‬\n‫الديــوان ملفــن لــكل قضيــة يشــتمل امللــف علــى صحيفــة الدعــوى‬\n‫واألوراق الثبوتيــه للدعــوى ويحتفــظ الديــوان مبلــف وامللــف الثانــي يســلم‬\n‫للمدعــى عليــه ويســلم لــه مــن قبــل املدعــي ويوقــع علــى االســتالم وذلــك‬\n‫قبــل اجللســة األولــى ويكــون املوعــد محــدد مــن قبــل الديــوان وعندمــا‬\n‫حضرنــا يف اجللســة األولــى وجــرى ســؤال ‪...‬عــن جوابــه عــن الدعــوى لــم‬\n‫يحضــر اجلــواب وجــرى تأجيــل اجللســة لذلــك‪ ،‬وبعــد اخلــروج مــن مجلــس‬\n‫القضــاء قــام املدعــى عليــه فاستفســر مــن ديــوان املظالــم هــل النظــام‬\n‫يســمح لــه بالترافــع وحضــور اجللســات فأجيــب بنعم فقام بفســخ وكالته‬\n‫بــدون ســابق إنــذار وطلــب مــن املدعــي الســجل التجــاري‪ ،‬ويف هــذه‬\n‫اجللســة حضــر الطرفــان وأبــرز املدعــي شــهادة تســجيل فــرع مؤسســة‬\n‫اســم التاجــر رباعيــا‪ ،... /‬رقــم الســجل املدنــي ‪...‬تاريــخ ‪1386/4/13‬ه ـ‬\n‫مصدرهــا ظهــران اجلنــوب‪ ،‬املركــز الرئيســي يف اخلبــر الثقبــة‪ ،‬االســم‬\n‫التجــاري للفــرع مكتــب ‪...‬لتحصيــل الديــون لصاحبهــا ‪ ،...‬النشــاط‬\n‫مزاولــة حتصيــل الديــون نيابــة عــن الغيــر مبوجــب الترخيــص رقــم ‪357‬‬\n‫يف ‪1416/3/6‬ه ـ يف الســجل الصــادر مــن الدمــام برقــم (‪ )...‬يف‬\n‫‪1418/9/22‬هــ‪ ،‬وباالطــاع علــى االتفاقيــة بــن الطرفــن واملعنونــة‬\n\n\n                                                                                   ‫‪252‬‬\n\f      ‫مبكتــب (‪ )...‬لالستشــارات القانونيــة وحتصيــل الديــون ســجل جتــاري‬\n      ‫(‪ )...‬وبســؤال املدعــي عــن اختــاف رقــم الســجل علــى مطبوعاتــه وعــن‬\n      ‫رقــم الســجل الــذي احضــره فأجــاب‪ :‬بــأن لديــه ســجل رئيســي فطلــب‬\n      ‫منــه إحضــار الســجل الرئيســي واســتعد بذلــك‪ ،‬ويف هــذه اجللســة حضــر‬\n      ‫الطرفــان وبطلــب الســجل مــن املدعــي أبــرز شــهادة شــطب الصــادرة مــن‬\n      ‫فــرع وزارة التجــارة والصناعــة باملنطقــة الشــرقية مــن مكتــب الســجل‬\n      ‫التجــاري بالدمــام برقــم ‪ 365/‬يف ‪1428/4/8‬ه ـ اســم التاجــر ‪...‬االســم‬\n      ‫التجــاري مؤسســة ‪...‬للمقــاوالت العامــة رقــم القيــد بالســجل‬\n      ‫‪ 2050033333‬وتاريــخ ‪1428/9/20‬ه ـ العنــوان الدمــام عمــارة (‪)...‬‬\n      ‫ســبب الشــطب انتقــال املؤسســة مــن الدمــام إلــى اخلبــر وذلــك اعتبــارا‬\n      ‫مــن ‪1428/4/8‬ه ـ انتهــى ويالحــظ أن تاريــخ الســجل يف ‪1428/9/20‬هـ‬\n      ‫وتاريــخ الشــطب يف ‪1428/4/8‬ه ـ وســوف يتــم الكتابــة لفــرع التجــارة‬\n      ‫للتأكــد مــن تاريــخ الســجل‪ ،‬ويف جلســة أخــرى حضــر املدعــي وحضــر‬\n      ‫املدعــى عليــه وكالــة ‪...‬احلامــل للبطاقــة رقــم (‪... )...‬الــخ‪ ،‬وقــد جــرى‬\n      ‫الكتابــة إلــى فــرع وزارة التجــارة للمنطقــة الشــرقية باخلطــاب رقــم‬\n      ‫‪ 30/14766‬يف ‪1430/6/2‬ه ـ وذلــك بطلــب التأكــد مــن تاريــخ الســجل‬\n      ‫التجــاري مــع توضيــح نشــاط الســجل التجــاري وقــد أعيــدت األوراق مــن‬\n      ‫فضيلــة الرئيــس برقــم ‪ 30/16261‬يف ‪1430/6/15‬ه ـ شــرحا علــى‬\n      ‫خطــاب مديــر فــرع وزارة التجــارة والصناعــة باملنطقــة الشــرقية رقــم‬\n      ‫‪/15/6943‬ن د يف ‪1430/6/13‬ه ـ واملتضمــن بــأن تاريــخ الســجل رقــم‬\n      ‫‪ 2050033333‬هــو ‪1418/9/21‬ه ـ وأن نشــاطه مقــاوالت عامة للمباني‬\n      ‫إنشــاء ـ إصــاح ـ هــدم ـ ترميــم ومرفــق نســخة مــن احلاســب اآللــي‪،‬‬\n      ‫وأضــاف املدعــي قائــا بــأن ســجل التحصيــل رقمــه (‪ )...‬وعنــد شــطب‬\n\n\n‫‪253‬‬\n\f‫الســجل الرئيســي مت تغييــر رقــم ســجل حتصيــل الديــون لــذا ســوف يتــم‬\n‫الكتابــة لفــرع وزارة التجــارة والصناعــة باملنطقــة الشــرقية لطلــب‬\n‫اإلفــادة عــن مــا ذكــر املدعــي‪ ،‬ويف جلســة أخــرى حضــر الطرفــان‬\n‫وجــرى الكتابــة إلــى مديــر عــام فــرع وزارة التجــارة والصناعــة باملنطقــة‬\n‫الشــرقية برقم ‪ 30/21489‬يف ‪1430/8/7‬هـ بطلب اإلفادة عن الســجل‬\n‫رقم‪2050033333001/‬مــع توضيــح نشــاط الســجل ووردت لنــا اإلجابــة‬\n‫مــن فضيلــة الرئيــس برقــم‪ 30/22887/‬يف ‪1430/8/24‬ه ـ شــرحا علــى‬\n‫خطــاب مديــر عــام فــرع وزارة التجــارة الصناعــة باملنطقــة الشــرقية رقــم‬\n‫‪/15/9620‬ق ر يف ‪1430/8/19‬ه ـ واملتضمــن أن املواطــن ‪ ...‬ســجل‬\n‫جتــاري رقــم (‪ )...‬وتاريــخ ‪1418/9/22‬ه ـ اخلــاص مبكتــب ‪ ...‬لتحصيــل‬\n‫الديــون لصاحبــه ‪ ...‬ونشــاطه مزاولــة حتصيــل الديــون نيابــة عــن الغيــر‬\n‫مبوجب الترخيص رقم ‪ 357‬يف ‪1416/8/6‬هـ حســب املســتخرج املرفق‬\n‫أ‪.‬ه ـ ويف يــوم االثنــن املوافــق ‪1433/02/15‬ه ـ افتتحــت اجللســة الســاعة‬\n‫العاشــرة وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ ...‬وحضــر حلضــوره املدعــى عليــه ‪ ...‬مصــري اجلنســية مبوجــب رخصــة‬\n‫إقامــة رقــم (‪ )...‬وبطلــب جــواب املدعــي علــى مــا ورد يف كالم املدعــى‬\n‫عليــه وكالــة يف اجللســة الســابقة قــال ليــس عنــدي ســوى مــا قدمتــه‬\n‫ســابق ًا ثــم طلبنــا مــن املدعــي تقــدمي صــور مــن األحــكام الصــادرة مــن‬\n‫ديــوان املظالــم واملتضمنــة مــا يــدل علــى حضــوره اجللســات والترافــع فيهــا‬\n‫فقــدم احلكــم الصــادر مــن احملكمــة اإلداريــة بالدمــام رقــم‬\n‫‪/192‬د‪/‬ت‪/‬ج‪ 15 /‬يف القضيــة رقــم ‪/ 3 /1063‬ق كمــا قــدم صــورة مــن‬\n‫احلكــم الصــادر مــن احملكمــة اإلداريــة بالدمام رقــم ‪/112‬د‪/‬ت‪/‬ج‪15/‬‬\n‫يف القضيــة رقــم ‪ / 3 / 1065‬ق ثــم قــال أن املعاملــة تتضمــن مكاتبــات‬\n\n\n                                                                                     ‫‪254‬‬\n\f      ‫بــن ديــوان املظالــم وبــن ناظــر القضيــة الســابق الشــيخ ‪...‬أرغــب منكــم‬\n      ‫اإلطــاع عليهــا بنــاء عليــه فقــد رفعــت اجللســة لالطــاع علــى املكاتبــات‬\n      ‫الســابقة بــن ديــوان املظالــم وبــن فضيلــة الشــيخ ‪...‬إلــى يــوم الســبت‬\n      ‫املوافــق ‪1433/05/01‬ه ـ الســاعة التاســعة‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى‬\n      ‫اهلل على نبينا محمد وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪1433/02/15‬هـ‬\n      ‫ويف يــوم الســبت املوافــق‪ 1433/05/01‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 09 : 03‬وفيهــا حضــر ‪...‬وحضــر حلضــوره املدعــى عليــه وكالــه ‪...‬‬\n      ‫وقــد جــرى مراجعــة مــا ذكــره املدعــي أصالــة يف اجللســة الســابقة‬\n      ‫مــن اإلطــاع علــى اخلطابــات الصــادرة مــن ديــوان املظالــم فوجــدت انــه‬\n      ‫صــدر خطــاب مــن رئيــس فــرع ديــوان املظالــم مبنطقــة املدينــة املنــورة‬\n      ‫برقــم ‪/1/22/3020‬د يف ‪1428/7/3‬ه ـ واخلطــاب رقــم ‪/1/22/269‬د‬\n      ‫يف ‪1429/1/14‬ه ـ واملتضمــن مــا نصــه نفيدكــم أن املدعــو ‪...‬تقــدم‬\n      ‫بدعــوى ســجلت لــدى الديــوان برقــم ‪/5/22/1‬ق لعــام ‪1426‬ه ـ وكالــة‬\n      ‫عــن ‪...‬ضــد مكتــب املهنــدس ‪...‬وقــد وردت للفــرع بتاريــخ ‪1426/1/3‬ه ـ‬\n      ‫وحكــم بهــا بتاريــخ ‪1426/1/9‬ه ـ باحلكم املرفق رقــم ‪/55‬د‪/‬ت ج‪21/‬‬\n      ‫لعــام ‪1426‬ه ـ بعــدم اختصــاص ديــوان املظالــم والئيــا بنظــر الدعــوى وقد‬\n      ‫حضــر جلســة احلكــم املدعــي أصالــة وأيــد احلكــم مــن هيئــة التدقيــق‬\n      ‫بحكمهــا رقــم ‪/314‬ت‪ 3/‬لعــام ‪1426‬ه ـ وتقبلــوا فضيلتكــم خالــص‬\n      ‫التقديــر أ‪.‬ه ـ كمــا جــرى اإلطــاع علــى خطــاب رئيــس فــرع ديــوان‬\n      ‫املظالــم باملنطقــة الشــرقية رقــم د‪/‬ت‪/‬ج‪ 287/15/‬يف ‪1428/8/21‬ه ـ‬\n      ‫املتضمــن نفيدكــم أن املدعــو ‪...‬تقــدم بالوكالــة عــن املدعــو ‪...‬بأربــع‬\n      ‫لوائــح دعــوى كال منهــا مــن ورقــة واحــدة ومــع كل الئحــة عــدد مــن‬\n      ‫املرفقــات وجــرى قيــد كل منهــا قضيــة مســتقلة وهــي القضايــا رقــم‬\n\n\n‫‪255‬‬\n\f‫‪/3/1062‬ق ورقــم ‪/3/1063‬ق ورقــم ‪/3/1064‬ق ورقــم ‪/3/1065‬ق‬\n‫وذلــك للعــام ‪1425‬ه ـ وحضــر الوكيل يف اجللســة األولى فقط للقضيتني‬\n‫رقــم ‪/3/1062‬ق ورقــم ‪/3/1064‬ق ولــم يحضــر يف جلســات القضيتــن‬\n‫األخريــن إلحاطــة فضيلتكــم أ‪.‬ه ـ وبعــد اإلطــاع علــى جميــع القــرارات‬\n‫الصــادرة مــن ديــوان املظالــم واخلطابــات الصــادرة مــن فرعــي ديــوان‬\n‫املظالــم باملدينــة املنــورة والدمــام وكــذا بعــد اإلطــاع علــى اخلطــاب‬\n‫الصــادر مــن األمــن العــام بغرفــة الشــرقية رقــم ‪ 34300/99/1740‬يف‬\n‫‪1429/7/2‬ه ـ املتضمــن تقديــر أتعــاب املدعــي بأربعــن الــف ريــال عليــه‬\n‫فإننــا نــرى إعــادة الكتابــة إلــى الغرفــة التجاريــة مــع كامــل مــا اســتجد‬\n‫مــن خطابــات وقــرارات لتقديــر مــا يســتحقه املدعــي بصفتــه شــخص‬\n                  ‫غيــر مختــص وغيــر ملــم بالنواحــي النظاميــة والشــرعية‬\n‫ويف يــوم االثنــن املوافــق‪ 1433/07/21‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪ 09.30‬وفيهــا حضــر املدعــي ‪...‬وحضــر حلضــوره املدعــى عليــه ‪...‬وقــد‬\n‫وردنــا خطــاب الغرفــة التجاريــة برقــم ‪ 340200/171/890‬يف‬\n‫‪1433/06/21‬هـ املتضمن (( أو ًال ‪ -‬أن املدعي يستحق مبلغ ( ‪40.000‬‬\n                         ‫ألــف ريــال ) أربعــون الــف ريــال نظيــر مــا قــام بــه‬\n‫مــن جهــد وهــذا املبلــغ يشــمل مصاريــف التقاضــي والســفر بصفتــه‬\n‫وكيــل وهــذا مــا مت توضيحــه وفقــا لــرأي فريــق العمــل املشــكل‬\n‫لدراســة القضيــة مبوجــب خطابنــا رقــم ‪ 34300/99/1740‬بتاريــخ‬\n‫‪2008/07/05‬م ثاني ـ ًا ‪ -‬أمــا فيمــا يتعلــق بانتحــال صفــة احملامــي فهــذا‬\n‫يخضــع إلــى العقوبــات املقــررة يف نظــام احملامــاة والئحتــه التنفيذيــة‬\n‫وعليــه فــإن جلنــة احملامــن تــرى بــأن املدعــي ‪...‬يســتحق مبلــغ وقــدره‬\n‫أربعــون الــف ريــال لقــاء جهــده يف نقــل البيانــات مــن ملفــات موكلــه إلــى‬\n\n\n                                                                                       ‫‪256‬‬\n\f      ‫الئحــة الدعــوى وتكاليــف الســفر )) أ‪.‬ه ـ بنــاء علــى الدعــوى واإلجابــة‬\n      ‫وجميــع مــا تقــدم ولكــون املدعــي عليــه ‪...‬تعاقــد مــع املدعــي ‪...‬باعتبــاره‬\n      ‫محاميـ ًا متخصصـ ًا يف الشــريعة والقانــون‪ ،‬ولكــون املدعــي قــام بإيهــام‬\n      ‫كتــب عليهــا العقــد منصــوص‬      ‫املدعــى عليــه بذلــك ‪ ،‬فمطبوعاتــه التــي ُ‬\n      ‫يف أعالهــا عبــارة‪( :‬مكتــب ‪...‬لالستشــارات القانونيــة وحتصيــل‬\n      ‫الديــون) وال شــك أن ذلــك تدليــس ظاهــر وغــش فاحــش‪ ،‬وقــد ســبق‬\n      ‫الكتابــة منــا إلــى فــرع وزارة التجــارة والصناعــة فــورد جوابهــم أن‬\n      ‫نشــاط املدعــي ينحصــر يف حتصيــل الديــون نيابــة عــن الغيــر وال دخــل‬\n      ‫لالستشــارات القانونيــة يف نشــاطه‪ ،‬وقــد ورد يف املــادة ‪ 1/37‬مــن نظــام‬\n      ‫احملامــاة‪ (( :‬يكــون الشــخص منتحــا صفــة احملامــي إذا قــام بعمــل‬\n      ‫يجعــل لــه صفــة احملامــي‪ ،‬ومــن ذلــك‪ :‬فتــح مكتــب الســتقبال قضايــا‬\n      ‫ـات إلــى نفســه بصفــة‬  ‫الترافــع واالستشــارات‪ ،‬أو اإلشــارة يف مطبوعـ ٍ‬\n      ‫احملامــي )) وقــد اتفــق أهــل العلــم رحمهــم اهلل علــى حرمــة الغــش ســواء‬\n      ‫كان بالقــول ‪ ،‬أو الفعــل ‪ ،‬وســواء كان بكتمــان العيــب يف املعقــود‬\n      ‫عليــه‪ ،‬أو الثمــن ‪ ،‬أو بالكــذب واخلديعــة‪ ،‬وســواء كان يف املعامــات‪،‬‬\n      ‫أو يف غيرهــا مــن املشــورة والنصيحــة ‪ ،‬قــال الترمــذي رحمــه اهلل ‪ -‬ســن‬\n      ‫الترمــذي مــع التحفــة ‪ 544/4 -‬مــا نصــه‪ (( :‬والعمــل علــى هــذا عنــد أهــل‬\n      ‫العلــم ‪ ..‬وقالــوا الغــش حــرام )) وقــد جــاء يف الصحيحــن مــن حديــث أبــي‬\n      ‫هريــرة رضــي اهلل عنــه أن رســول اهلل صلــى اهلل عليــه وســلم قــال‪ (( :‬وال‬\n      ‫ُتصــروا اإلبــل والغنــم ‪ ،‬فمــن ابتاعهــا بعــد ذلــك ‪ ،‬فهــو بخيــر النظريــن‬\n      ‫بعــد أن يحلبهــا ‪ ،‬إن رضيــا أمســكها ‪ ،‬وإن ســخطها ردهــا وصاعـ ًا مــن‬\n      ‫متــر )) فــا يســتحق املدعــي مــا ورد يف العقــد ؛ ألن مــا ُبنــي علــى باطــل‬\n      ‫فهــو باطــل ‪ ،‬ولكنــه يســتحق أجــرة مثلــه مــن املخلصــن واملعقبــن؛‬\n\n\n‫‪257‬‬\n\f‫ويخــرج علــى هــذه الصــورة مــا ذكــره‬        ‫وذلــك حلصــول العمــل منــه ‪ُ ،‬‬\n‫املــرداوي رحمــه اهلل يف اإلنصــاف ‪ 394/6‬حيــث قــال‪ (( :‬تنبيــه ‪ :‬مــراد‬\n‫املصنــف وغيــره ‪ :‬بقولهــم « ومــن عمــل لغيــره عمــا بغيــر جعــل فــا شــيء‬\n‫لــه « غيــر املعــد ألخــذ األجــرة ‪ ،‬فأمــا املعــد ألخذهــا ‪ :‬فلــه األجــرة قطعــا‬\n‫كاملــاح ‪ ،‬واملــكاري ‪ ،‬واحلجــام ‪ ،‬والقصــار ‪ ،‬واخليــاط ‪ ،‬والــدالل ‪،‬‬\n‫ونحوهــم ممــن يرصــد نفســه للتكســب بالعمــل ‪ ،‬فــإذا عمــل ‪ :‬اســتحق‬\n‫أجــرة املثــل ‪ ،‬نــص عليــه )) ‪ ،‬وقــال العالمــة منصــور البهوتــي رحمــه‬\n‫اهلل يف كشــاف القنــاع كتــاب اجلعالــة ‪ (( :485/9‬ومــن عمــل لغيــره‬\n‫عمــا بغيــر ُجعــل فــا شــيء لــه ) ؛ ألنــه بــذل منفعتــه مــن غيــر عــوض فلــم‬\n‫يســتحقه ‪ ،‬ولئــا يلــزم اإلنســان مــا لــم يلتزمــه ‪ ،‬ولــم تطــب نفســه بــه (‬\n‫إن لــم يكــن ) العامــل ( معــد ًا ألخــذ األجــرة ‪ ،‬فــإن كان ) معــد ًا لذلــك‬\n‫( كاملــاح ‪ ،‬وا ُملــكاري ‪ ،‬واحلجــام ‪ ،‬والقصــار ‪ ،‬واخليــاط ‪ ،‬والــدالل ‪،‬‬\n‫ونحوهــم ) كالنقــاد ‪ ،‬والكيــال ‪ ،‬والــوزان ‪ ،‬وشــبههم ( ممــن يرصــد‬\n‫نفســه للتكســب بالعمــل ‪ ،‬وأذن لــه ) املعمــول لــه يف العمــل ( فلــه أجــرة‬\n‫املثــل ) لداللــة العــرف علــى ذلــك ( وتقــدم معنــاه يف اإلجــارة )) وقــد أفــاد‬\n‫أهــل اخلبــرة أن أجــرة مثلــه قدرهــا ‪ 40000‬ريــال‪ ،‬بنــاء علــى مــا ســبق‬\n‫فقــد ثبــت لــدي تدليــس وغــش املدعــي ‪...‬بانتحالــه مهنــة ال ُيتقنهــا ولــم‬\n‫يرخــص لــه فيهــا فــا يســتحق مــا ورد يف العقــد وإمنــا يســتحق أجــرة مثلــه‬\n‫فيمــا عملــه مبلــغ ‪ 40000‬ريــال يدفعهــا املدعــى عليــه (‪ )...‬للمدعــي (‪)...‬‬\n‫حــا ًال وبــه حكمــت وبالنســبة النتحــال املدعــي ‪...‬مهنــة ال ُيتقنهــا ولــم‬\n‫يرخــص لــه فيهــا فســيجري بعــث أوراقــه جلهــة االختصــاص للتحقيــق‬\n‫معــه ومعاقبتــه حســب مــا ورد يف املــادة ‪ 37‬مــن نظــام احملامــاة وبعــرض‬\n‫احلكــم علــى الطرفــن قــررا عــدم قناعتهمــا باحلكــم وجــرى إفهامهمــا‬\n\n\n                                                                                         ‫‪258‬‬\n\f      ‫مبراجعــة احملكمــة بتاريــخ ‪1433/08/28‬ه ـ وذلــك لتمتعــي بإجــازة‬\n      ‫تبــدأ بتاريــخ ‪1433/07/23‬ه ـ وذلــك الســتالم صــورة مــن الصــك‪ .‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                               ‫يف ‪1433/07/21‬ه‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n      ‫وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى يف‬\n      ‫محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة العامــة مبدينــة الدمــام برقــم ‪28/19355‬‬\n      ‫وتاريــخ ‪1433/11/29‬ه ـ واملقيــدة لــدى احملكمــة برقــم ‪332195148‬‬\n      ‫وتاريــخ ‪1433/12/20‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n      ‫القاضــي باحملكمــة الشــيخ‪ /‬د‪... .‬املسـ ّـجل برقــم ‪ 33408025‬وتاريــخ‬\n      ‫‪1433/9/11‬ه ـ اخلــاص بدعوى‪.../‬ضــد‪ (... /‬مصــري اجلنســية )‬\n      ‫يف قضيــة حقوقيــة وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو‬\n      ‫مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحتــن‬\n      ‫االعتراضيتــن وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ولبيــان‬\n              ‫ذلــك جــرى حتريــره يف ‪1434/2/19‬هــ‪ ،‬واهلل ولــي التوفيــق‪.‬‬\n\n\n\n\n‫‪259‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":241,"source_page_end":259,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"200e65f3c4f4b5c36b510327a2bc69d06e7b29ebc0da15a7ce37f9f070b1c801","normalized_text_hash":"c0c0da52655650fb362a5cc3529ea9986fb6186370c2be560dd436fb940ccdb0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p241-33408025"},{"id":"af79d6d0-a86d-535e-a98b-828def5b6f18","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -استشارات اداريه وتربويه -مطالبة بباقي األتعاب -وجوب الوفاء بالعقود -ثبوت الدعوى -الزام املدعى عليه بدفع املبلغ","document_number":"33447677","case_number":"3256634","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":"الدائرة احلقوقية الثانية مبحكمة الاستئناف باملنطقة الشرقية برقم","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/8","year":"1434","subject":"عقد -استشارات اداريه وتربويه -مطالبة بباقي األتعاب -وجوب الوفاء بالعقود -ثبوت الدعوى -الزام املدعى عليه بدفع املبلغ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪33447677 :‬تاريخه‪1433/11/8 :‬هـ‬\n                   ‫رقم الدعوى‪3256634 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n   ‫‪/34186865‬ق‪/2‬أ تاريخه‪1434/4/14 :‬هـ‬\n\n\n‫عقــد ‪ -‬استشــارات اداريــه وتربويــه ‪ -‬مطالبــة بباقــي األتعــاب ‪ -‬وجــوب‬\n‫الوفــاء بالعقــود‪ -‬ثبــوت الدعــوى ‪ -‬الــزام املدعــى عليــه بدفــع املبلــغ‬\n                                                                ‫املدعــى بــه ‪.‬‬\n\n\n\n\n              ‫‪ -1‬قول اهلل تعالى‪(( :‬يا أيها الذين آمنوا أوفوا بالعقود))‪.‬‬\n                            ‫‪ -2‬املادة (‪ )55‬من نظام املرافعات الشرعية‪.‬‬\n                                 ‫‪ -3‬االصل يف العقود و الشروط احلل ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بأنــه اتفــق مــع املدعــى عليــه علــى أن يقــدم لــه شــخصي ًا‬\n‫استشــارات إداريــة وتربويــة للمــدة واألتعــاب املذكوريــن يف دعــواه‬\n‫وأنــه عمــل مــع املدعــى عليــه طــوال مــدة العقــد إال أنــه لــم يســلمه باقــي‬\n‫األتعــاب املســتحقة لــه‪ ،‬لــذا طلــب إلزامــه بدفــع كامــل املبلــغ املتبقــي‬\n‫لــه يف ذمتــه‪ -‬أقــر وكيــل املدعــى عليــه بالعقــد محــل الدعــوى ودفــع‬\n‫بــأن املدعــي ال يســتحق شــيئ ًا مــن األتعــاب املتفــق عليهــا ألنــه لــم يقــدم‬\n‫استشــارات ملوكلــه كمــا أن املشــروع الــذي مت االتفــاق معــه علــى تقــدمي‬\n‫االستشــارات بشــأنه قــد مت إغالقــه‪ -‬قــدم املدعــي للمحكمــة عقــد‬\n‫العمــل املبــرم مــع املدعــى عليــه كمــا قــدم مجموعــة مــن االستشــارات‬\n\n                                                                                        ‫‪260‬‬\n\f      ‫التــي ســبق لــه تقدميهــا لــه‪ -‬إذا تعاقــد الطرفــان عقــد ًا صحيح ـ ًا وجــب‬\n      ‫الوفــاء بــه‪ ،‬ومبــا فيــه مــن التزامــات‪ ،‬ومــا تضمنــه مــن شــروط‪ ،‬وصــارت‬\n      ‫الذمــة مشــغولة بــه حتــى يؤديــه يف موعــده وبشــروطه‪ -‬قضــت احملكمــة‬\n      ‫بإلــزام املدعــى عليــه بدفــع املبلــغ املدعــى بــه لصالــح املدعــي والــذي‬\n      ‫ميثــل باقــي أتعابــه عــن عقــد االستشــارات محــل الدعــوى‪ -‬قنــع املدعــي‬\n      ‫باحلكــم وعــارض عليــه املدعــى عليــه ‪ -‬قــررت محكمــة االســتئناف‬\n                                                          ‫املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪........‬القاضــي يف احملكمــة العامــة‬\n      ‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالدمــام برقــم ‪ 3256634‬وتاريــخ ‪ 1432/02/27‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 32175950‬وتاريــخ ‪ 1432/02/27‬ه ـ ففــي يــوم‬\n      ‫االثنــن املوافــق‪ 1432/06/20‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 00‬‬\n      ‫وفيهــا حضــر ‪........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬‬\n      ‫ويف يــوم الســبت املوافــق ‪1432/12/23‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n      ‫املدعــي ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬‬\n      ‫وحضــر حلضــوره ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ ........‬الشــرعي عــن ‪ ........‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل‬\n      ‫الدمــام الثانيــة رقــم ‪ 31919‬يف ‪1432/06/25‬ه وبســؤال املدعــي عــن‬\n      ‫دعــواه قــال لقــد جــرى االتفــاق بينــي وبــن املدعــى عليــه أصالــة ‪........‬‬\n      ‫علــى أن أقــوم بتقــدمي استشــارات إداريــة وتربويــة لــه شــخصي ًا ومــدة‬\n      ‫العقــد ثــاث ســنوات مقابــل إتعــاب شــهرية قدرهــا أربعــة عشــر الــف‬\n\n‫‪261‬‬\n\f‫ريــال شــهري ًا وقــد عملــت طــوال مــدة العقــد مــع املدعــى عليــه وقــد دفــع‬\n‫لــي مبلــغ مائتــان وثمانــون الــف ريــال مــن مجمــوع املبلــغ املســتحق وقــدره‬\n‫أربعمائــة وعشــرون الــف ريــال واملتبقــي يف ذمــة املدعــى عليــه مبلــغ مائــة‬\n‫وأربعــون الــف ريــال اطلــب احلكــم عليــه وإلزامــه بدفــع كامــل املبلــغ‬\n‫املتبقــي يف ذمتــه وقــدره مائــة وأربعــون الــف ريــال هــذه دعــواي وبعــرض‬\n‫ذلــك علــى املدعــى عليــه وكالــة قــال جميــع مــا ذكــره املدعــي يف دعــواه‬\n‫صحيــح ولكنــي اطلــب مــن املدعــي بيــان باالستشــارات التــي قدمهــا‬\n‫ملوكلــي خــال مــدة العقــد وال يخفــى أن القاعــدة الشــرعية تنــص علــى‬\n‫أن األجــر مقابــل العمــل واملدعــي لــم يقــدم أي استشــارة بنــاء عليــه فــا‬\n‫يســتحق املبلــغ الــذي أدعــى بــه علمـ ًا بــأن موكلــي لديــه مــا يثبت أنه ســلم‬\n‫للمدعــي زيــادة علــى املبلــغ املذكــور يف الدعــوى وســوف أقدم يف اجللســة‬\n‫القادمــة كامــل اإلثباتــات هــذا مــا لــدي وعنــد هــذا املوضــع طلبنــا مــن‬\n‫املدعــي إحضــار االتفاقيــة املبرمــة بينــه وبــن املدعــى عليــه كمــا طلبنــا‬\n‫مــن املدعــى عليــه وكالــة تقــدمي كشــف باملبالــغ املســلمة للمدعــي ويف‬\n‫يــوم الســبت املوافــق ‪1433/02/13‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n‫املدعــي ‪........‬ولــم يحضــر املدعــي وال وكيــل عنــه ونظــر ًا لتبلغــه مبوعــد‬\n‫اجللســة يف اجللســة الســابقة ســيجري مواصلــة النظــر يف الدعــوى حســب‬\n‫املــادة ‪ 55‬مــن نظــام املرافعــات الشــرعية وبســؤال املدعــي عمــا طلــب‬\n‫منــه يف اجللســة الســابقة قــال اقــدم لفضيلتكــم صــورة مــن االتفاقيــة‬\n‫املبرمــة بينــي وبــن املدعــى عليــه وباالطــاع عليهــا وجدتهــا محــررة علــى‬\n‫مطبوعــات اإلدارة العامة‪........‬ومختومــة باخلتــم الرســمي مبــدارس ‪........‬‬\n‫وبتوقيــع طــريف النــزاع ونصهــا كالتالــي (( اتفاقيــة أتعــاب إضافيــة‬\n‫احلمــد هلل رب العاملــن والصــاة والســام علــى ســيدنا محمــد وأصحابــه‬\n\n\n                                                                                       ‫‪262‬‬\n\f      ‫إلــى يــوم الديــن وبعــد فقــد اتفــق كل مــن ‪ -:‬الطــرف األول ‪ ........ :‬ســجل‬\n      ‫مدنــي رقــم ‪ ........‬الرئيــس العــام ملعاهــد ومــدارس ‪ -.........‬الطــرف الثاني‬\n                             ‫‪ ........ :‬ســجل مدنــي رقــم ‪ ........‬علــى البنــود التاليــة‪:‬‬\n      ‫‪ 1-‬يقــوم الطــرف الثانــي بتقــدمي استشــارات إداريــة وتربويــة للطــرف‬\n      ‫األول ‪ -2‬يقــوم الطــرف األول بدفــع أتعــاب تلــك االستشــارات لصالــح‬\n      ‫الطــرف الثانــي مبلــغ وقــدرة ( ‪ ) 14000‬أربعــة عشــر ألــف ريــال ال غيــر‬\n      ‫شــهريا ملــدة عشــرة اشــهر مــن كل عــام وملــدة ثــاث ســنوات تــودع يف‬\n      ‫حســاب الطــرف الثانــي ابتــداء مــن شــهر أكتوبــر لعــام ‪ 2007‬م ‪-3‬‬\n      ‫يلتــزم الطــرف األول بدفــع املبلــغ املتبقــي مــن األتعاب املذكــورة يف البند‬\n      ‫ثانيــا أعــاه لصالــح الطــرف الثانــي يف حــال رغبتــه يف إنهــاء االتفاقيــة‬\n      ‫مــع الطــرف الثانــي يف حالــة عــدم وجــود أســباب تخالــف البنــد رابعــا‬\n      ‫‪ -4‬أي جتــاوزات أو مخالفــات أنظمــة وسياســات مــدارس ‪ ....‬أو تقــدمي‬\n      ‫استشــارات إداريــة أو تربويــة تخالــف ألنظمــة وزارة التربيــة والتعليــم‬\n      ‫مــن الطــرف الثانــي مــن حــق الطــرف األول إنهــاء االتفاقيــة املبرمــة بــن‬\n      ‫الطرفــن بــدون صــرف باقــي األتعــاب املاليــة املســتحقة‪-5 .‬يعتبــر البنــد‬\n      ‫الثالــث الغيـ ًا يف حالــة رغبــة الطــرف الثانــي إنهــاء االتفاقيــة قبــل وقتهــا‬\n      ‫املذكــور يف البنــد الثانــي ‪.‬وقــد جــرى إعــداد االتفاقيــة مــن نســختني‬\n      ‫وعلــى ذلــك جــرى التوقيــع )) أ‪.‬ه ـ ثــم قــال املدعــي بالنســبة ملــا ذكــره‬\n      ‫املدعــى عليــه وكالــة وطلبــه بيــان باالستشــارات التــي قدمتهــا ملوكلــه‬\n      ‫فأقــول جميــع االستشــارات التــي قدمتهــا كانــت شــفويه حيــث كان‬\n      ‫يطلــب منــي االستشــارة مشــافهة ولــو طلبهــا منــي محــررة لقدمتهــا لــه‬\n      ‫حســب طلبــه وأقــدم لفضيلتكــم بعــض تلــك املواضيــع التــي استشــارني‬\n      ‫فيهــا وســوف أقدمهــا يف اجللســة القادمــة بــإذن اهلل تعالــى ويف جلســة‬\n\n\n‫‪263‬‬\n\f‫أخــرى حضــر املدعــي ‪........‬ولــم يحضــر املدعــى عليــه ‪........‬وال وكيــا‬\n‫عنــه مــع تبلغــه مبوعــد اجللســة حســب إقــرار الوكيــل الشــرعي ‪........‬‬\n‫املــؤرخ يف ‪1433/2/13‬ه ـ وبســؤال املدعــي عــن مــا طلــب منــه يف‬\n‫اجللســة الســابقة قــال باإلشــارة الــى جــواب املدعــى عليــه الــذي ذكــر‬\n‫فيــه ان القاعــدة تنــص علــى ان االجــر مقابــل العمــل و اننــي لــم اقــدم‬\n‫أي استشــارة لــه ‪ ،‬وبنــاء عليــة ذكــر بأنــي ال اســتحق املبلــغ الــذي‬\n‫ادعــي بــه اوجــز ردي يف نقطتــن ‪-:‬او ًال ‪ :‬العقــد شــريعة املتعاقديــن‬\n‫والعقــد مســتويف اركانــه وشــروطه و اوصافــه ســليمة ال خلــل فيهــا ‪،‬‬\n‫فيجــب بنــاء علــى ذلــك االلتــزام والوفــاء بــكل مــا يلتــزم بــه املتعاقــدان‬\n‫ويشــترطانه ‪ ،‬قــال تعالــى يف ســورة املائــدة (( أوفــوا بالعقــود )) وقــال‬\n‫الرســول الكــرمي صلــى اهلل عليــه وســلم ( املؤمنــون علــى شــروطهم )‬\n‫ثاني ًا ‪ :‬يف قول املدع ــى عليه أن االج ــر مقابل العمل فالق ــاعدة الق ــانونية‬\n‫تق ــول انــه ( ال عمــل إال بتكليــف) وكل مــا مت تكليفــي بــه اجنزته وهلل‬\n‫احلمــد ( ارفــق لفضيلتكــم بعــض األعمــال التــي قمــت بهــا والتــي توضــح‬\n‫االلتــزام الكامــل بالعقــد مــن قبلــي )‪ .‬وعليــه اطلــب مــن فضيلتكــم‬\n‫احلكــم علــى املدعــى عليــه بكامــل املبلــغ املتبقــي ‪.‬وفيمــا يلــي بعــض‬\n‫االستشــارات التــي مت تقدميهــا لألســتاذ ‪ - ........ /‬دراســة أســباب ضعــف‬\n‫خطــوط االتصــال اإلداري والتربــوي يف االجتاهــن مــن اعلــي ألســفل‬\n‫والعكــس بــن إدارة املــدارس يف كل مــن ( الدمــام ‪ ،‬اخلبــر ‪ ،‬اجلبيــل)‬\n‫و اإلدارة العامــة ملــدارس ‪ ( ........‬تداخــل املهــام ‪ ،‬الهيــكل التنظيمــي‬\n‫لــإدارة العامــة ‪ ،‬آليــة اختيــار اإلداريــن‪ ،‬عــدم وضــوح قنــوات ‪........‬يف‬\n‫االجتاهــن)‪ -.‬تخفيــض تكاليــف اإلعــداد للحفــل اخلتامــي للمــدارس‬\n‫بإقامة حفل كل مرحلة ثانوية يف كل مدرســة بصورة منفصلة ( كل‬\n\n\n                                                                                      ‫‪264‬‬\n\f      ‫مدرســة تقيــم حفلهــا الســنوي يف مقــر املدرســة ‪ ،‬نقــل احلفــل لألســر عبــر‬\n      ‫الشــبكة الداخليــة او عبــر االنترنــت)‪ -.‬إنشــاء معامــل افتراضيــة للعلــوم‬\n      ‫يف املرحلــة املتوســطة و( الكيميــاء ) للمرحلــة الثانويــة بديــا عــن العمــل‬\n      ‫التقليــدي خلفــض التكاليــف وحمايــة الطــاب واملعلمــن مــن أخطــار‬\n      ‫املــواد الكيميائيــة ( حتديــد الشــركات التــي تقدم املعامــل االفتراضية‬\n      ‫‪ ،‬تقــدمي العــروض ‪ ،‬التعاقــد بحيــث يشــمل العقــد التركيــب والصيانــة‬\n      ‫والتدريــب)‪- .‬مشــروع يــوم دراســي خــارج املدرســة للصفــوف األوليــة‬\n      ‫يف املــدارس ( املرحلــة االبتدائيــة ) علــى الشــاطئ أو يف احــد احلدائــق‬\n      ‫داخــل املدينــة وتنفيــذ البرنامــج بكامــل طاقــم املدرســة ( تشــكيل‬\n      ‫اللجــان ‪ ،‬حتديــد امليزانيــات ‪ ،‬مخاطبــة اجلهــات ذات االختصــاص ‪،‬‬\n      ‫التنفيــذ)‪ -‬توظيــف مشــاركة املــدارس يف الســباق اخليــري الســنوي‬\n      ‫الــذي تقيمــه مــدارس ‪ ........‬األهليــة يف التســويق للمــدارس ( إعــداد‬\n      ‫مطويــات ونشــرات صحيــة‪ ،‬اإلعــان املباشــر ورعايــة الســباق‪ ،‬تدريــب‬\n      ‫الطــاب لضمــان املشــاركة اإليجابيــة)‪ -‬تقــدمي حوافــز ألوليــاء أمــور‬\n      ‫طــاب املدرســة (‪ )........‬بعــد أغالقهــا ونقلهــم ملــدارس‪ ........‬عنــد‬\n      ‫التحاقهــم مبــدارس اخلبــر (إعفائهــم مــن رســوم املواصــات) كحافــز‬\n      ‫لضمــان اســتمرارهم يف املدرســة وعــدم ســحب ملفاتهــم مــن املدرســة‪.‬‬\n      ‫‪ -‬أقامــة مناســبات مبســطة للمعلمــن اجلــدد بدايــة كل عــام دراســي‬\n      ‫جديــد يف كل مدرســة مــن املــدارس للترحيــب بهــم ودمجهــم باملجتمــع‬\n      ‫التربــوي للمــدارس (حتديــد شــكل املناســبة‪ ،‬حتديــد امليزانيــة مــن بنــد‬\n      ‫املصروفــات لــكل مدرســة)‪ -.‬االســتفادة مــن إمكانــات معاهــد‪....‬‬\n      ‫املختلفــة واملتطــورة للتدريــب يف تدريــب العاملــن يف املــدارس لإليفــاء‬\n      ‫مبتطلبــات البرامــج التدريبيــة املطلوبــة مــن وزارة التربيــة والتعليــم (‬\n\n\n‫‪265‬‬\n\f‫خفــض التكاليــف ‪ ،‬اكتشــاف طاقــات املعلمــن‪ ،‬اعطــاء املــدارس‬\n‫ميــزة تنافســية يف تطويــر املعلمــن لديهــا )‪ - .‬مشــروع تبــادل الزيــارات‬\n‫التدريبــي بــن معلمــي املــدارس يف كل مــن الدمــام واخلبــر واجلبيــل (‬\n‫االســتفادة مــن وجــود املعلمــن يف املــدارس يــوم اخلميــس للتدريــب وتبــادل‬\n‫اخلبــرات بينهــم)‪ - .‬اســتغالل املســاحة االضافيــة يف مبنــى مــدارس ‪....‬‬\n‫باجلبيــل يف إقامــة مضمــار للخيــل ميكــن ان يخــدم املــدارس (ماديـ ًا مــن‬\n‫خــال االشــتراكات ‪ ،‬بدنيــا ‪ ،‬إعالنيـاً‪ ،‬اجتماعيـاً) ‪ ،‬وكذلــك ملعــب‬\n‫كــرة قــدم مــزروع بالعشــب ميكــن ان يخــدم طــاب املدرســة واملــدارس‬\n‫القريبــة يف اجلبيــل ( أنشــطة املدرســة‪ ،‬اســتضافة مســابقات رياضيــة‬\n‫باملدرســة ‪ ،‬تأجيــر امللعــب يف الفتــرات املختلفــة ملــن يرغــب إلقامــة‬\n‫املســابقات املدرســية و االنشــطة الترفيهيــة علــى امللعــب ) ‪ .‬اســتقطاب‬\n‫برامــج تدريبيــة ملعلمــي التعليــم العــام ( وزارة التربيــة والتعليــم ) يتــم‬\n‫تنفيذهــا يف املــدارس لضمــان مشــاركة معلمــي املــدارس الكتســاب‬\n‫اخلبــرة واحلصــول علــى شــهادات تدريــب معتمــدة مــن وزارة التربيــة‬\n                                                                       ‫والتعليــم ‪.‬‬\n‫رعايــة مســابقات علميــة وأنشــطة مدرســية (رعايــة األنشــطة واملســابقات‬\n‫ماليــا‪ ،‬اســتضافتها يف مرافــق املدرســة ‪ ،‬اإلعــان عــن املــدارس مــن‬\n‫خــال هــذه األنشــطة)‪ -.‬فصــل مبنــى املرحلة االبتدائيــة يف مدارس اخلبر‬\n‫عــن املرحلــة االبتدائيــة واســتكمال جتهيزاتهــا (الســاحة‪ ،‬معمــل تربيــة‬\n‫فنية‪ ،‬ســبورات ذكية ‪ ) ...‬الســتيعاب عدد اكبر من األعداد احلالية‪-.‬‬\n‫االســتفادة مــن املســبح املوجــود يف مــدارس الدمــام يف أقامــة مســابقات‬\n‫وأنشــطة للمــدارس احمليطــة ( اإلعــان عــن مســابقات يف الســباحة ‪،‬‬\n‫تقــدمي اجلوائــز ‪ ،‬اإلعــان عــن املــدارس مــن خاللها)‪ -.‬تطويــر املطبوعات‬\n\n\n                                                                                      ‫‪266‬‬\n\f      ‫التــي تصدرهــا املــدارس بصــورة دوريــة بحيــث تصبــح تربويــة متخصصــة‬\n      ‫بــدال مــن توجههــا احلالــي نحــو اجلانــب الدعائــي املباشــر هــذا مــا لــدي‬\n      ‫ويف جلســة أخــرى وفيهــا حضــر املدعــي ‪........‬وحضــر حلضــوره املدعــى‬\n      ‫عليــه وكالة‪........‬ســعودي بالســجل املدنــي رقــم ‪........‬الوكيــل الشــرعي‬\n      ‫عــن ‪ ........‬مبوجــب وكالتــه عــن ‪ ........‬مبوجــب الوكالــة الصــادرة مــن‬\n      ‫كتابــة عــدل الثانيــة بالدمــام برقــم ‪ 3365952‬يف ‪1433/05/05‬ه ـ‬\n      ‫واملخــول لــه يف املطالبــة وإقامــة الدعــاوى واملرافعــة واملدافعــة لــدى‬\n      ‫احملاكــم اإلداريــة إلــى أخــره ثــم قــال املدعــى عليــه وكالــة ‪ :‬إشــارة‬\n      ‫إلــى الئحــة الدعــوى املقامــة مــن قبــل املدعــي نفيــد فضيلتكــم بأنهــا‬\n      ‫دعــوى باطلــة وغيــر مقبولــة ويتضــح ذلــك مــن مطالعــة دفاعنــا وجوابنــا‬\n      ‫فنقــول وبــاهلل التوفيــق أو ًال ‪ :‬ندفــع باســتحالة تنفيــذ عقــد االستشــارات‬\n      ‫ســند املدعــي يف الدعــوى ‪ :‬حيــث أن محــل هــذا العقــد كان تقــدمي‬\n      ‫استشــارات تربويــة وإداريــة ملدرســة ‪....‬باخلبــر وحيــث أنــه قــد مت إغــاق‬\n      ‫املدرســة نظــر ًا النخفــاض عــدد الطــاب مــن ثــم فقــد أصبحــت عدميــة‬\n      ‫اجلــدوى النعــدام العائــد املــادي وحتقيــق خســائر ملوكلــي ‪ ،‬لذلــك فــا‬\n      ‫مجــال لتطبيــق العقــد بعــد انتهــاء محلــه ثانيـ ًا ‪ :‬ندفــع بخلــو الدعــوى مــن‬\n      ‫ثمــة أيــة مســتندات تثبــت قيــام املدعــي تنفيــذ عقــد االستشــارات ‪ :‬إذ‬\n      ‫يتضــح لفضيلتكــم مــن مطالعــة أوراق املعاملــة والدعــوى أنهــا دعــوى‬\n      ‫مقطوعــة وغيــر موصولــة بالدليــل والبينــة‪ ،‬إذ أن هــذا العقــد ُيكيــف‬\n      ‫مــن الناحيــة الشــرعية علــى أنــه عقــد مــن عقــود املعاوضــة وتبــادل‬\n      ‫املنفعــة حيــث ال تنشــأ االلتزامــات علــى طرفيــه إال بعــد تبــادل املنفعــة‬\n      ‫بــن الطرفــن وحيــث إن املدعــي لــم يقــدم ملوكلــي أي استشــارة تربويــة‬\n      ‫أو إداريــة بــأي شــكل مــن األشــكال ســواء كانــت مكتوبــة أو شــفوية‬\n\n\n‫‪267‬‬\n\f‫ولــم يقــم بدعــم موكلــي باملشــورة يف أي موضــوع يخــص املدرســة لذلــك‬\n‫فــا حــق للمدعــي يف املطالبــة بقيمــة االستشــارات التــي ليــس لهــا وجــود‬\n‫وعليــه فــان دعــواه تكــون باطلــة الفتقارهــا لســند شــرعي صحيــح ثالثـاً‪:‬‬\n‫ندفــع بــأن اســتالم املدعــي أليــة مبالــغ ماليــة مت دون وجــه حــق ‪ :‬حيــث أن‬\n‫تلــك املبالــغ مت حتويلهــا يف حســاب املدعــي مــن قبــل محاســب موكلــي‬\n‫(املدعــي ) الــذي ظــن خطــأ منــه بــان العقــد ســاري املفعــول وظــل يرســل‬\n‫يف حســاب املدعـ ـ ـ ـ ـ ــي تلــك املبالــغ التــي اســتولى عليهــا دون وجــه حــق‪،‬‬\n‫ونفيدكــم بــان موكلــي بصــدد رفــع دعــوى قضائيــة ضــد املدعــي‬\n‫إللزامــه بــرد املبالــغ التــي حولــت إليــه رابع ـ ًا نتمســك بإحالــة الدعــوى‬\n‫إلــى هيئــة النظــر يف احملكمــة لتقديــر قيمــة األعمــال واالستشــارات‬\n‫التــي يطالــب املدعــي بقيمتهــا مــن موكلــي ‪ :‬وذلــك حتــى يتــم تقديــر‬\n‫االستشــارات التــي يدعــي بهــا املدعــي إذا اســتطاع تقــدمي البينــة علــى‬\n‫أنــه قدمهــا ملوكلــي مبــا يتناســب مــع قيمتهــا املماثلــة لنظيرهــا يف‬\n‫الســوق بنــاء عليــه أطلــب احلكــم بالطلبــات التاليــة ‪-1‬احلكــم بــرد‬\n‫الدعــوى لكونهــا باطلــة وغيــر موصولــة ومنقطعــة الدليــل والبينــة‬\n‫‪-2‬إلــزام املدعــى عليــه بدفــع مبلــغ ‪ 50.000‬خمســون ألــف ريــال مقابــل‬\n‫أتعــاب احملامــاة عــن تلــك الدعــوى هــذا مــا لــدي ثــم طلــب املدعــى عليــه‬\n‫وكالــة ســؤال املدعــي هــل عمــل املدعــي مديــر ًا ملدرســة ‪ ........‬باخلبــر ام‬\n‫ال فأجــاب املدعــي ان هــذا الســؤال ليــس مــن صلــب القضيــة ولكنــي‬\n‫أفيدكــم بأنــي عملــت مديــر ًا ملــدارس ‪ ........‬يف اخلبــر واجلبيــل قبــل واثنــاء‬\n‫وبعــد عقــد االستشــارات املبــرم بينــي وبــن ‪....‬كمــا طلــب املدعــى عليــه‬\n‫وكالــة تزويــده بصــورة مــن االستشــارات الشــفوية التــي قدمهــا املدعــي‬\n‫يف اجللســة الســابقة كما طلبنا منه ســؤال موكله هل طلب من املدعي‬\n\n\n                                                                                         ‫‪268‬‬\n\f      ‫‪ ......‬اي استشــارات اداريــة وتربويــة خــال فتــرة العقــد ام ال ويف جلســة‬\n      ‫أخــرى حضــر املدعــي ‪ ........‬وحضــر حلضــوره املدعــى عليــه وكالــة ‪........‬‬\n      ‫ونظــرا لكــون الوكالــة التــي يحملهــا االخيــر ال تخولــه حــق االقــرار‬\n      ‫فقــد طلبنــا منــه تعديــل وكالتــه فأبــدى اســتعداده ويف جلســة أخــرى‬\n      ‫حضــر املدعــي ‪ ........‬وحضــر حلضــوره املدعــى عليــه وكالــة ‪ ........‬وقــد‬\n      ‫أبــرز الوكالــة املعدلــة واملخولــة لــه حــق املرافعــة واملدافعــة واإلنــكار‬\n      ‫واإلقــرار وقبــول االحــكام واالعتــراض عليهــا وطلــب االســتئناف‬\n      ‫حســب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بالدمــام رقــم‬\n      ‫‪ 33351745‬يف ‪1433/11/2‬ه ـ ثــم قــال املدعــى عليــه وكالــه أصــادق‬\n      ‫وأقــر مبــا أقــر بــه املدعــي مــن أنــه أســتلم مــن موكلــي مبلــغ ‪280000‬‬\n      ‫ريــال وأكتفــي مبــا قدمتــه يف مذكرتــي املؤرخــة يف ‪1433/5/25‬ه ـ‬\n      ‫فبنــاء علــى مــا تقــدم وبعــد ســماع الدعــوى واإلجابــة وجميــع مــا ســبق‬\n      ‫فقــد تقــدم املدعــي ‪........‬بدعــوى للمطالبــة مببلــغ ‪ 140000‬ريــال وهــذا‬\n      ‫املبلــغ ميثــل باقــي أتعابــه عــن عقــد االستشــارات املبــرم بينــه وبــن املدعــى‬\n      ‫عليــه ‪ ،........‬وبعــد تأمــل القضيــة وأوراق املعاملــة والعقــد املبــرم بــن‬\n      ‫طــريف النــزاع ونصــوص الفقهــاء رحمهــم اهلل جنــد أنــه إذا تعاقــد‬\n      ‫الطرفــان عقــد ًا صحيح ـ ًا وجــب الوفــاء بــه‪ ،‬ومبــا فيــه مــن التزامــات‪،‬‬\n      ‫ومــا تضمنــه مــن شــروط‪ ،‬وصــارت الذمــة مشــغولة بــه حتــى يؤديــه يف‬\n       ‫ـوا َأ ْو ُفـ ْ‬\n      ‫ـوا‬          ‫آم ُنـ ْ‬\n                         ‫موعــده وبشــروطه‪ ،‬واهلل عــز وجــل يقــول‪َ ( :‬يــا َأ ُّي َهــا الَّذِ يـ َـن َ‬\n      ‫ِبا ْل ُع ُقــو ِد )‪ ،‬وإن األصــل يف العقــود والشــروط احلــل وال يحــرم إال مــا نــص‬\n      ‫عليــه وحيــث ال نــص بتحرميــه فيبقــى علــى أصــل اإلباحــة‪ ،‬وتعتبــر عقــود‬\n      ‫االستشــارات مــن العقــود احلديثــة وبتأملهــا جنــد أنهــا تتضمــن مصلحــة‬\n      ‫محضــة للطرفــن‪ ،‬خاصــة املستشــير وهــو هنــا املدعــى عليــه‪ ،‬فيحصــل‬\n\n\n‫‪269‬‬\n\f‫لــه فائدتــان األولــى‪ :‬االطمئنــان واالســتقرار بوجــود املستشــار عنــد‬\n‫طلبــه‪ ،‬والثانيــة‪ :‬مصلحــة جتاريــة كبيــرة حــن يعلــم الطــاب وأوليــاء‬\n‫أمورهــم أن املنشــأة التعليميــة التــي يرأســها املدعــى عليــه تتعامــل مــع‬\n‫خبــراء ومستشــارين يف اإلدارة والتربيــة‪ ،‬ومــن املهــم أن ُيعلــم أن العقــد‬\n‫املبــرم بــن طــريف النــزاع ُحـ ِـر َر علــى مطبوعــات معاهــد ومــدارس ‪........‬‬\n‫ووقــع عليــه املدعــى عليــه بصفتــه الرئيــس العــام للمعاهــد واملــدارس‪،‬‬\n‫وهــذا االطمئنــان واألمــان الــذي يجــده املدعــى عليــه ومــن يتعامــل معــه‬\n‫يصلــح أن يكــون عوضـ ًا مقابــل األتعــاب‪ ،‬وذلــك كعقــد احلراســة لقــاء‬\n‫مبلــغ معــن وهــي إجــارة مقابــل احلصــول علــى األمــان املتأتــي مــن هــذا‬\n‫العقــد‪ ،‬بنــاء علــى مــا ســبق فقــد ألزمــت املدعــى عليــه ‪ ........‬بدفــع مبلــغ‬\n‫‪ 140000‬ريــال لصالــح املدعــي ‪ ........‬وهــذا املبلــغ ميثــل باقــي أتعابــه‬\n‫عــن عقــد االستشــارات املذكــور وبــه حكمــت وبعــرض ذلــك علــى‬\n‫الطرفــن قــرر املدعــي قناعتــه باحلكــم أمــا املدعــى عليــه فقــرر عــدم‬\n‫القناعــة وجــرى إفهامــه أن عليــه مراجعــة احملكمــة خــال عشــرة أيــام‬\n‫الســتالم نســخة مــن احلكــم ثــم تبــدأ املــدة االعتراضيــة وأن عليــه تقــدمي‬\n‫الئحتــه خــال ثالثــن يومــا فــإذا لــم يقــدم اعتراضــه خــال هــذه املــدة‬\n‫ســقط حقــه يف طلــب االســتئناف واكتســب احلكــم القطعيــة وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                       ‫حــرر يف ‪ 1433/11/3‬هـ ـ‬\n‫ففــي يــوم الســبت املوافــق ‪1434/05/18‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪ 11:30‬وقــد جــرى رفــع املعاملــة الــى محكمــة االســتئناف وأعيــدت‬\n‫لنــا مــن فضيلــة الرئيــس وقيــدت باحملكمــة برقــم ‪ 34953292‬يف‬\n‫‪1434/4/17‬ه ـ مرفقــا بهــا القــرار الصــادر من اصحــاب الفضيلة قضاة‬\n\n\n                                                                                        ‫‪270‬‬\n\f      ‫الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف باملنطقــة الشــرقية برقــم‬\n      ‫‪/34186865‬ق‪/2‬أ يف ‪1434/4/14‬ه ـ املتضمنــة املصادقــة على احلكم‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                  ‫وســلم‪ .‬حــرر يف ‪1434/5/18‬ه ـ‬\n\n\n\n\n‫‪271‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":260,"source_page_end":271,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"82e59a582ffe8307169c4daff93dd9ba37e58b4a990af16b404afd3ac6a0bab1","normalized_text_hash":"a70f08c2fb583a894f1b16ba1f9001332d934fc77ac44c0e41c2c79c20afe284","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p260-33447677"},{"id":"460393f6-faab-5d07-ab40-cfd1ac3e4341","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -عماله منزليه -مطالبة تنفيذ العقد أو دفع ما غرمه ألجل االستقدام -مترجم لالجنبي -دفع املدعى عليها بأن العمل شاق وإصرارها على االمتناع عن العمل -طلب تفسير املشقة وظهور عدم صحة ما دفعت به -إلزام املدعى عليها بدفع ما غرمه ألجل","document_number":"33407931","case_number":"33529827","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/9/11","year":"1434","subject":"عقد -عماله منزليه -مطالبة تنفيذ العقد أو دفع ما غرمه ألجل االستقدام -مترجم لالجنبي -دفع املدعى عليها بأن العمل شاق وإصرارها على االمتناع عن العمل -طلب تفسير املشقة وظهور عدم صحة ما دفعت به -إلزام املدعى عليها بدفع ما غرمه ألجل","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33407931 :‬تاريخه‪1433/9/11 :‬هـ‬\n                   ‫رقم الدعوى‪33529827 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3445488‬تاريخه‪1434/2/24 :‬هـ‬\n\n\n‫عقــد ‪ -‬عمالــه منزليــه ‪ -‬مطالبــة تنفيــذ العقــد أو دفــع مــا غرمــه ألجــل‬\n‫االســتقدام ‪ -‬مترجــم لالجنبــي ‪ -‬دفــع املدعــى عليهــا بــأن العمــل شــاق‬\n‫وإصرارهــا علــى االمتنــاع عــن العمــل ‪ -‬طلــب تفســير املشــقة وظهــور‬\n‫عــدم صحــة مــا دفعــت بــه ‪ -‬إلــزام املدعــى عليهــا بدفــع مــا غرمــه ألجــل‬\n                                                                      ‫االســتقدام‪.‬‬\n\n\n\n\n                                      ‫ما أشار له القاضي يف تسبيب احلكم‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بدعــوى ضــد املدعــى عليهــا بأنــه اســتقدمها للعمــل لديــه‬\n‫خادمــة منزليــة ملــدة ســنتني وقــام بدفــع اثنــي عشــر ألــف ريــال أجــرة‬\n‫اســتقدام وألفــي ريــال تأشــيرة إال أنهــا هربــت بعــد ثالثــة أيــام مــن‬\n‫قدومهــا لديــه ويطلــب إلزامهــا بالعمــل لديــه أو دفــع مــا غرمــه بســببها‬\n‫أربعــة عشــر ألــف ريــال ‪ -‬أقــرت املدعــى عليهــا بالدعــوى إال أنهــا قــررت‬\n‫بأنهــا ال تعلــم صحــة مــا ادعــاه مــن خســارة وأنهــا غيــر مســتعدة للعمــل‬\n‫لديــه لكونــه شــاقا ‪ -‬ســألت الدائــرة عــن نــوع املشــقة التــي تواجههــا‬\n‫املدعــى عليهــا فأجابــت بــأن البيــت كبيــر والعمــل كثيــر ‪ -‬أنكــر‬\n‫املدعــي بــأن العمــل لديــه شــاق ‪ -‬فجــرى ســؤال املدعــي البينــة علــى مــا‬\n\n                                                                                     ‫‪272‬‬\n\f      ‫غرمــه فأبــرز ســند حتويــل مصــريف وتأشــيرة العمــل ‪ -‬إلقــرار املدعــى‬\n      ‫عليهمــا مبــا ادعــى بــه املدعــي إال قــدر مــا دفعــه وبنــاء علــى ســند احلوالــة‬\n      ‫والتأشــيرة ولعــدم وجاهــة مــا دفعــت بــه حيــث لــم تذكــر أمــرا خارجــا‬\n      ‫عــن العــادة واملشــقة أمــر الزم للعمــل وال تنفــك عنــه عليــه وألن عقــد‬\n      ‫االجــارة عقــد الزم ال يجــوز فســخه إال برضــا الطرفــن وألن املدعــي‬\n      ‫طالــب فيمــا لــو أصــرت املدعــى عليهــا علــى االمتنــاع وفســخ العقــد دفــع‬\n      ‫مــا غرمــه ألجــل العقــد مــن أجــرة اســتقدام ورســوم تأشــيرة لــذا فقــد‬\n      ‫حكمــت الدائــرة علــى املدعــى عليهــا بدفــع مــا غرمــه املدعــي بســبب‬\n      ‫العقــد ‪ -‬قــررت املدعــى عليهــا االعتــراض بــدون الئحــة ‪ -‬صــدق احلكــم‬\n                                                             ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n      ‫احلمد هلل وحده وبعد فلدي أنا ‪ ..........................‬القاضي يف احملكمة‬\n      ‫اجلزائيــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة بالريــاض برقــم ‪ 33529827‬وتاريــخ ‪1433/08/17‬‬\n      ‫ه ـ املقيــدة باحملكمــة برقــم ‪ 331549109‬وتاريــخ ‪ 1433/08/17‬ه ـ‬\n      ‫ففــي يــوم الثالثــاء املوافــق‪ 1433/08/20‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 12 : 30‬وفيهــا حضــر ‪ ..........................‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ……………‪ .‬الوكيــل عــن ‪ .....................‬ســجله‬\n      ‫املدني ‪ ...........................‬بالوكالة رقم ‪ 33380026‬يف ‪1433/8/14‬هـ‬\n      ‫الصــادرة مــن كتابــة عــدل عرقــة ولــه فيهــا حــق املرافعــة واملدافعــة‬\n      ‫والصلــح والتنــازل وحضــرت حلضــوره ‪ ...................‬ســيرالنكية اجلنســية‬\n      ‫مبوجــب ورقــة رعايــة شــؤون اخلادمــات برقــم ‪ ...............‬يف ‪1433/8/3‬ه ـ‬\n\n‫‪273‬‬\n\f‫وادعــى األول قائــا لقــد قــام موكلــي باســتقدام هــذه احلاضــرة للعمــل‬\n‫ملــدة ســنتني ومت دفــع مبلــغ وقــدره اثنــا عشــر ألــف ريــال رســوم اســتقدام‬\n‫باإلضافــة إلــى مبلــغ ألفــي ريــال تأشــيرة عمــل وحضــرت لــدى موكلــي‬\n‫يوم اجلمعة ‪1433/7/11‬هـ وبقيت لديه حتى يوم األحد ‪1433/7/13‬هـ‬\n‫ثــم هربــت لــذا فإننــي أطلــب عودتهــا للعمــل أو إعــادة مجمــوع مــامت دفعــه‬\n‫وقــدره أربعــة عشــر ألــف ريــال هــذه دعــواي وبســؤال املدعــى عليهــا عــن‬\n‫دعــوى املدعــي أجابــت بواســطة مترجــم احملكمــة املتعــاون ‪...................‬‬\n‫ســيرالنكي اجلنســية باإلقامــة رقــم ‪ ................‬قائلــة ماذكــره املدعــي‬\n‫كلــه صحيــح لكــن املبلــغ الــذي دفعــه ال أعلــم صحته وأنا غير مســتعدة‬\n‫للعمــل حيــث أن العمــل شــاق هكــذا أجابــت وبعرضــه علــى املدعــي قــال‬\n‫إنهــا لــم تعمــل لــدى موكلــي إال ثالثــة أيــام ولــم يكــن هنــاك مشــقة‬\n‫هكــذا قــرر فجــرى ســؤالها عــن نــوع املشــقة التــي واجهتهــا فقالــت إن‬\n‫البيــت كبيــر والعمــل كثيــر هكــذا قــررت وبعرضــه علــى املدعــي‬\n‫قــال إن موكلــي لــم يكلفهــا بأعمــال شــاقة هكــذا قــرر فجــرى ســؤاله‬\n‫البينــة علــى املبلــغ الــذي دفعــه وعلــى التأشــيرة فأبــرز ورقــة حتويــل علــى‬\n‫مطبوعــات شــركة ‪ .............‬برقــم ‪ 30518037‬يف ‪1433/07/07‬ه ـ‬\n‫بإســم ‪ ..................‬مببلــغ وقــدره اثنــا عشــر ألفــا وخمســة عشــر ريــاال‬\n‫وأربــع هلــات محــول إلــى ‪ ...‬ســيرالنكا وبعــرض الورقــة علــى املدعــى‬\n‫عليهــا قالــت ليــس لــدي اي شــيء بهــذا اخلصــوص كمــا أبــرز تأشــيرة‬\n‫العمــل رقــم ‪ 2370874470‬يف ‪1433/07/07‬ه ـ وكتــب فيهــا املهنــة‬\n‫عاملــة منزليــة للعمــل لــدى ‪ ..................‬فجــرى ســؤال الطرفــن عــن‬\n‫الراتــب الشــهري املتفــق عليــه واليوميــة فأجابــا قائلــن بأنــه مبلــغ وقــدره‬\n‫ســتمائة وخمســون ريــاال فتكــون اليوميــة اثنــان وعشــرون ريــاال هكــذا‬\n\n\n                                                                                       ‫‪274‬‬\n\f      ‫قــررا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ونظــرا إلقــرار املدعــى‬\n      ‫عليهــا بدعــوى املدعــي كاملــة ســوى مــا يتعلــق مببلــغ اإلســتقدام وبنــاء‬\n      ‫علــى احلوالــة املثبتــة والتأشــيرة وألن دفعهــا باملشــقة ال وجاهــة لــه حيــث‬\n      ‫لــم تذكــر أمــرا خارجــا عــن العــادة واملشــقة الزمــة للعمــل ال تنفــك عنــه‬\n      ‫وحيــث قــد تســببت بالضــرر للمدعــي برفضهــا للعمــل وملــا قــرره الفقهــاء‬\n      ‫من أن اإلجارة عقد الزم بني الطرفني ال يجوز فسخه إال برضى الطرف‬\n      ‫اآلخــر أو بســبب شــرعي لذلــك كلــه فقــد حكمــت علــى املدعــى عليهــا‬\n      ‫‪ ................‬بإلزامهــا بتســليم مبلــغ وقــدره أربعــة عشــر ألــف ريــال للمدعي‬\n      ‫أصالــة ‪ ......................‬وبعرضــه عليهــا قــررت عــدم القناعــة دون تقــدمي‬\n      ‫الئحــة وأقفلــت اجللســة الســاعة ‪ 01.30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر ونطــق احلكــم يف‬\n      ‫‪ 1433/08/20‬ه ـ ‪ .‬احلمــد هلل وحــده وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة‬\n      ‫الدائــرة السادســة لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف‬\n      ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزئيــة‬\n      ‫بالريــاض برقــم ‪ 331549109‬وتاريــخ ‪1434/2/5‬ه املرفــق بهــا الصــك‬\n      ‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪.........................../‬‬\n      ‫املســجل برقــم ‪ 33407931‬وتاريــخ ‪1433/9/11‬ه اخلــاص بدعــوى ‪/‬‬\n      ‫ا عــن ‪ .................‬ضــد ‪( .................. /‬ســيرالنكية‬ ‫‪.................‬وكي ـ ً‬\n      ‫اجلنســية) يف مبلــغ مالــي علــى الصفــة املوضحــة بالصــك واملتضمــن‬\n      ‫حكــم فضيلتــه بإلــزام املدعــى عليهــا بدفــع مبلــغ وقــدره أربعــة عشــر‬\n      ‫ألــف ريــال للمدعــي أصالــة‪ ،‬وبدراســة الصــك وصــورة ضبطــه وأوراق‬\n      ‫املعاملــة قررنــا باألكثريــة املصادقــة علــى احلكــم‪ .‬والل ــه املوفــق وصلــى‬\n                                 ‫اهلل علــى نبينــا محمـ ــد وآل ــه وصحب ــه وســلم ‪،،،،،،‬‬\n\n\n‫‪275‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":272,"source_page_end":275,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7cc0e13e42cf51c4ceaa2e445ff58bc844e9822788f976ec65a33a23c632559d","normalized_text_hash":"cfbdec9d3fe2bca600c33f18d418ba05d9d067b88fe65d06f4cb0e5de2b8ed04","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p272-33407931"},{"id":"8fa58bfd-2a7e-5c56-a637-e610d842af75","document_type":"judgment","category":"judicial","subcategory":"general","title":"أتعاب -منازعات محاماة -فسخ عقد وكالة محامي -مطالبة مدعي محاميا بإعادة الدفعة األولى من العقد لعدم التزامه ببنوده -إنكار املدعى عليه -إلزامهما بالتحكيم لتضمن العقد بندا يقضي الرجوع إليه حال النزاع -صرف نظر .","document_number":"3461567","case_number":"33573700","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/14","year":"1434","subject":"أتعاب -منازعات محاماة -فسخ عقد وكالة محامي -مطالبة مدعي محاميا بإعادة الدفعة األولى من العقد لعدم التزامه ببنوده -إنكار املدعى عليه -إلزامهما بالتحكيم لتضمن العقد بندا يقضي الرجوع إليه حال النزاع -صرف نظر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3461567 :‬تاريخه‪1434/3/14 :‬هـ‬\n                   ‫رقم الدعوى‪33573700 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34204483‬تاريخه‪1434/5/4 :‬هـ‬\n\n\n‫أتعــاب ‪ -‬منازعــات محامــاة‪ -‬فســخ عقــد وكالــة محامــي‪ -‬مطالبــة‬\n‫مدعــي محاميــا بإعــادة الدفعــة األولــى مــن العقــد لعــدم التزامــه‬\n‫ببنــوده ‪ -‬إنــكار املدعــى عليــه ‪ -‬إلزامهمــا بالتحكيــم لتضمــن العقــد‬\n             ‫بنــدا يقضــي الرجــوع إليــه حــال النــزاع ‪ -‬صــرف نظــر ‪.‬‬\n\n\n\n\n‫‪ .1‬نظــام التحكيــم الصــادر باملرســوم امللكــي رقــم م‪ 34/‬وتاريــخ‬\n‫‪1433/5/24‬ه ـ يف املــادة التاســعة ونصهــا‪( »:‬أ) يجــوز أن يكــون اتفــاق‬\n‫التحكيــم ســابقا علــى قيــام النــزاع ســواء أكان مســتقال بذاتــه أم ورد‬\n                                                             ‫يف عقــد معــن»‪.‬‬\n‫‪ .2‬الفقــرة الثالثــة مــن املــادة التاســعة مــن نظــام التحكيــم ونصهــا ‪:‬‬\n‫« يكــون إتفــاق التحكيــم مكتوب ـ ًا إذا تضمــن محــرر ًا صــادر ًا مــن طــريف‬\n‫التحكيــم أو إذا تضمنــه مــا تبــاداله مــن مراســات موثوقــة أو برقيــات‬\n‫أو غيرهــا مــن وســائل االتصــال االلكترونيــة أو املكتوبــة وتعــد اإلشــارة‬\n‫يف عقدهــا أو اإلحالــة فيــه إلــى مســتند يشــتمل علــى شــرط التحكيــم‬\n                                                      ‫مبثابــة اتفــاق حتكيــم»‪.‬‬\n\n\n\n\n                                                                                   ‫‪276‬‬\n\f      ‫تقــدم املدعــي بدعــوى ضــد املدعــى عليــه بأنــه قــام بتوكيلــه يف الترافــع‬\n      ‫عنــه يف قضيــة حقوقيــة وأنــه لــم يلتــزم بواجبــات العقــد بعــد اســتالمه‬\n      ‫للدفعــة األولــى ويطلــب إلزامــه بإعــادة املبلــغ املســلم وتعويضــه عــن‬\n      ‫كافــة األضــرار التــي حلقــت بــه بســببه ‪ -‬أقــر املدعــى عليــه بالعقــد‬\n      ‫والدفعــة األولــى وأنكــر عــدم إلتزامــه بالعقــد ودفــع بــأن املدعــي يهــدف‬\n      ‫إســقاط حقــه يف املطالبــة بباقــي املبلــغ وطلــب صــرف النظــر عــن دعــواه‬\n      ‫‪ -‬جــرى االطــاع علــى وثيقــة العقــد فظهــر بأنهمــا نصــا بأنــه يتــم معاجلــة‬\n      ‫أي نــزاع بينهمــا بالتحكيــم ‪ -‬عليــه وملــا ورديف نظــام التحكيــم الصــادر‬\n      ‫باملرســوم امللكــي رقــم م‪ 34/‬وتاريــخ ‪1433/5/24‬ه ـ يف املــادة التاســعة‬\n      ‫ونصهــا‪( »:‬أ) يجــوز أن يكــون اتفــاق التحكيــم ســابقا علــى قيــام النــزاع‬\n      ‫ســواء أكان مســتقال بذاتــه أم ورد يف عقــد معــن»‪ ،‬وملــا ورود يف الفقــرة‬\n      ‫الثالثــة مــن ذات املــادة ونصهــا ‪ « :‬يكــون إتفــاق التحكيــم مكتوبـ ًا إذا‬\n      ‫تضمــن محــرر ًا صــادر ًا مــن طــريف التحكيــم أو إذا تضمنــه مــا تبــاداله‬\n      ‫مــن مراســات موثوقــة أو برقيــات أو غيرهــا مــن وســائل االتصــال‬\n      ‫االلكترونيــة أو املكتوبــة وتعــد اإلشــارة يف عقدهــا أو اإلحالــة فيــه‬\n      ‫إلــى مســتند يشــتمل علــى شــرط التحكيــم مبثابــة اتفــاق حتكيــم»‬\n      ‫عليــه وملــا اشــتمل عليــه العقــد مــن النــص علــى اإلحالــة إلــى التحكيــم‬\n      ‫عنــد حــدوث أي نــزاع لــذا فقــد قــررت الدائــرة صــرف النظــر عــن دعــوى‬\n      ‫املدعــي كمــا قــررت صــرف النظــر عمــا طلبــه املدعــى عليــه وإفهامهمــا‬\n      ‫بأنــه يلزمهمــا إجــراء التحكيــم وفقــا ملــا اتفقــا عليــه وبذلــك حكمــت‬\n      ‫‪ -‬قــرر الطرفــان االعتــراض فأفهمــا بالتعليمــات ‪ -‬صــدق احلكــم مــن‬\n\n‫‪277‬‬\n\f                                                        ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......................‬القاضــي يف احملكمــة‬\n‫العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪33573700‬‬\n‫وتاريــخ ‪1433/09/13‬ه ـ املقيــدة باحملكمــة برقــم ‪331697472‬‬\n‫وتاريــخ ‪1433/9/12‬ه ففــي يــوم األحــد املوافــق ‪1433/11/14‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪01 : 00‬وفيهــا حضــر املدعــي ‪.........................‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقم………………‪.‬وادعــى‬\n‫علــى احلاضــر معــه يف مجلــس احلكــم ‪ ........................‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم …………………… دعــواي هــذه ضــد‬\n‫املدعــى عليــه املوضــح إســمه بعاليــه وموضــوع الدعــوى بالتفصيــل مــا‬\n‫يلــي‪ -:‬بتاريــخ ‪1432 / 2 / 8 :‬ه ـ املوافــق ‪ 2011 / 1 / 12 :‬م قمــت‬\n‫بالتعاقــد مــع املدعــو ‪ .……………………/‬للقيــام مبالحقــة املدعــو‪/‬‬\n‫‪ .....................‬قضائيـ ًا واملطالبــة بكامــل حقوقــي جتاهــه حســب العقــد‬\n‫املبــرم معــه‪ ،‬وقــد ســلمته مبلــغ ‪ 250.000‬ريــال فقــط مائتــان وخمســون‬\n‫ألــف ريــال مبوجــب شــيك رقــم ‪ 220‬مســحوب علــى مجموعــة ‪.......‬‬\n‫بتاريــخ ‪2011/1/12‬م نظيــر الدفعــة األولــى احملــددة يف العقــد ومت‬\n‫صــرف الشــيك يف حينــه‪ ،‬وحيــث أن بنــود العقــد حتــدد التزامــات‬\n‫الطرفــن ومنهــا التزامــات املدعــى عليــه كمــا هــو يف البنــد الســادس‬\n‫مــن العقــد وكذلــك أحــوال عــدم اســتحقاق املدعــى عليــه لألتعــاب مــع‬\n‫التزامــه بــرد األتعــاب املدفوعــة منــي وفســخ العقــد مــن طــريف لوحــدي‬\n\n                                                                                      ‫‪278‬‬\n\f      ‫كمــا هــو يف البنــد اخلامــس مــن العقــد‪ ،‬وحيــث مت خــرق بنــود العقــد مــن‬\n      ‫قبــل املدعــى عليــه وأخــل بالتزاماتــه وأضــر بــي وبقضيتــي ومبطالبتــي‬\n      ‫خلصمــي يف قضيــة املدعــو‪ ............ /‬كمــا هــو مشــروح يف خطابــي رقــم‬\n      ‫‪/8‬ص‪ 111219/‬بتاريــخ ‪1433/1/24‬ه ـ املوجــه للمدعــى عليــه واملرفــق‬\n      ‫صورتــه‪ ،‬وحيــث أن مــا ينــص بــه العقــد املبــرم معــه يحــدد طــرق حــل‬\n      ‫النــزاع ‪ -‬كمــا هــو يف البنــد احلــادي عشــر مــن العقــد بــأن يتــم حــل‬\n      ‫النــزاع ودي ـاً‪ ،‬فــإن تعــذر ذلــك يتــم اللجــوء إلــى التحكيــم وفــق نظــام‬\n      ‫التحكيــم الســعودي ويكــون بالرجــوع إلــى جلنــة التحكيــم بالغرفــة‬\n                                                         ‫التجاريــة الصناعيــة بجــدة‪.‬‬\n                                                                               ‫لطلبات‪:‬‬\n                 ‫‪ .1‬إلزام املدعى عليه برد مبلغ ( ‪250.000‬ريال ) املدفوعة له ‪.‬‬\n      ‫‪ .2‬إلــزام املدعــى عليــه ســداد مبلــغ ( ‪ 150.000‬ريــال ) أتعــاب محامــاة‬\n                                                                ‫واستشــارات قانونيــة‪.‬‬\n          ‫‪ .3‬إلزام املدعي عليه باملصاريف وأتعاب القضية مبا فيها التحكيم‬\n      ‫‪ .4‬إلــزام املدعــي عليــه بدفــع مبلــغ (‪ )2.000.000‬مليونــا ريــال عــن‬\n      ‫االضــرار التــي حلقــت بــي حتــى اآلن عــن ســوء إدارة القضيــة املوكلــة‬\n                                                                       ‫إليــه وتعطيلهــا‪.‬‬\n      ‫‪ .5‬إلــزام املدعــى عليــه وتكليفــه بســداد جميــع قيمــة األضــرار املاديــة‬\n      ‫واملعنويــة التــي حلقــت بــي أو أي غرامــات ماديــة أو تعويضــات أو رد إعتبار‬\n                                             ‫لطــرف ثالــث تســبب يف اإلضــرار بــه‪.‬‬\n      ‫املســتندات‪ -1 :‬صــور عقــد إتفــاق أتعــاب (عــدد ‪ 5‬لفــات) ‪ -2‬خطابــي‬\n                ‫املوجــه إليــه بفســخ العقــد بتاريــخ ‪1433/1/24‬ه ـ (عــدد ‪ 2‬لفــة)‬\n      ‫وأقــر بأنــه لــم يســبق أن تقدمــت مبثــل هــذه الدعــوى لهــذه احملكمــة أو‬\n\n\n‫‪279‬‬\n\f‫غيرهــا مــن اجلهــات القضائيــة األخــرى وأنــه إذا كانــت دعــواي هــذه‬\n‫غيــر صحيحــة أو كيديــة فللمدعــى عليــه حــق مطالبتــي مبــا حلقــه مــن‬\n‫ضــرر كمــا يحــق للجهــة املختصــة إحالتــي مــع املدعــي العــام للمحكمــة‬\n‫املختصــة ملجازاتــي وفــق مــا يقتضيــه الوجــه الشــرعي واألنظمــة‬\n‫والتعليمــات ‪ .‬هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه اجــاب بقولــه‬\n‫ســوف جنيــب عــن ذلــك يف اجللســة القادمــة ولذلــك رفعــت اجللســة ‪ ،‬ويف‬\n‫جلســة أخــرى حضــر الطرفــان وكان قــد حتــدد لهــذه اجللســة موعــدا يف‬\n‫‪1434/2/17‬ه ـ وتعــذر ضبــط اجللســة يف حينــه ونظــرا لوجــود عطــل يف‬\n‫النظــام وحــدد هــذا املوعــد بديــا للموعــد الســابق وبســؤال املدعــى عليــه‬\n‫عــن رده علــى دعــوى املدعــي الــذي اســتمهل ألجله أبــرز مذكرة مكونة‬\n‫مــن صفحتــن وملحــق بهــا عــدد مــن املرفقــات جــرى إيداعهــا يف املعاملــة‬\n‫ونصهــا التالــي « ردا علــى دعــوى املدعــي ‪،‬جنــد أن مــا ذكــره املدعــي يف‬\n‫دعــواه ادعــاء مرســل ال يقــوم علــى بينــة أو يســتند الــى دليــل بــل هــو إمعــان‬\n‫بــواح يف التعــدي وعــدم احتــرام حلجيــة العقــد احملرر بني طــريف التقاضي‬\n‫فيهــذه الدعــوى ‪،‬ونوضــح لفضيلتكــم ذلــك فيمــا يلــي‪-:‬او ًال ‪:‬حقيقــة‬\n‫الدعــوى بتاريــخ ‪1432/02/07‬ه ـ مت حتريــر عقــد أتعــاب بــن املدعــي‬\n‫وفــق بنــوده وشــروطه علــى أن أتولــى إقامــة دعــوى او دعــاوى لــدى اجلهــات‬\n‫املختصــة ضــد خصمــه املدعــو‪.................... /‬ملطالبتــه بحقــوق املدعــي‪،‬‬\n‫وبالفعــل تقدمــت إلــى مقــام محافظــة جــدة باملعاملــة رقــم‬\n‫(‪ )32202403242‬وحتــى أحيلــت إلــى احملكمــة وحضــرت جلســاتها‬\n‫التــي تداولــت ونقــدم لفضيلتكــم اخلطــاب رقــم (‪ )520‬وتاريــخ‬\n‫‪1432/08/02‬ه ـ واملوجــه الــي املدعــي الــذي يوضــح بعــض األعمــال‬\n‫التــي قمــت فيهــا ولــم يعتــرض املدعــي علــى أي إجــراء ويعتبــر ســكوت‬\n\n\n                                                                                          ‫‪280‬‬\n\f      ‫إقــرارا علــى صحــة وســامه جميــع اإلجــراءات دون إهمــال أو تقصيــر (‬\n      ‫اخلطــاب مرفــق رقــم ‪ )1‬ثاني ـ ًا ‪ :‬األصــل يف العقــود اللــزوم تعلمــون‬\n      ‫(يــا َأ ُّي َهــا‬\n                      ‫فضيلتكــم أن األصــل يف العقــود شــرع ًا ال ّلــزوم لقولــه تعالــي َ‬\n      ‫أن األصــل يف العقــود‬        ‫يف ‪ :‬اعلــم ّ‬                                    ‫آم ُنــوا َأ ْو ُفـ ْ‬\n                                                  ‫ـوا ِبا ْل ُع ُقــودِ) قــال القــرا ّ‬                ‫الَّذِ يـ َـن َ‬\n      ‫ال ّلــزوم ‪ ،‬وكمــا ال يخفــى علــي فضيلتكــم قاعــدة «املســلمون علــى‬\n      ‫شــروطهم « أي أن املســلم إذا اشــترط شــرطا أو ُشــرط عليــه شــرط فهــو‬\n      ‫ملــزم بهــذا الشــرط ‪ ،‬إال شــروطا حللــت محرمــا أو عكســه وهــذه‬\n      ‫القاعــدة أوجبــت علــى طــريف العقــد االلتــزام بهــذا الشــرط وبتطبيــق‬\n      ‫هــذه القواعــد الفقهيــة الشــرعية علــى دعــوى املدعــي وعقــد األتعــاب‬\n      ‫احملــرر بينــي وبــن املدعــي وفقــا لقاعــدة ( املســلمون علــى شــروطهم )‬\n      ‫جنــد أن دعــواه هــذه دعــوى اســتباقيه الغــرض منــه االلتفــاف حــول مــا‬\n      ‫يتوجــب الوفــاء بــه وهــو أتعابــي ألن عقــد األتعــاب احملــرر بــن طــريف‬\n      ‫التقاضــي يتوجــب العمــل بكافــة بنــوده اإللزاميــة مــن قبــل طرفيــه كمــا‬\n      ‫يتوجــب اإليفــاء مبــا ورد بــه مــن بنــود اشــترطها طرفيــه علــى أنفســهما ‪.‬‬\n      ‫ثالث ـ ًا ‪:‬دعــوى املدعــي دعــوى اســتباقية بغــرض عــدم مطالبتــي بحقوقــي‬\n      ‫الثابتــة بعقــد األتعــاب‪ .‬ســوء النيــة وقصــد اإلضــرار بــي متوفــر يف هــذه‬\n      ‫الدعــوى وليــس ادل علــى ذلــك مــن قيامــه بفســخ العقــد مــن جهتــه فقــط‬\n      ‫وإخطــاري بذلــك ومــا يؤكــد ذلــك هــو عــدم قيامــه بتجديــد للوكالــة‬\n      ‫لكــف يــدي عــن إمتــام عملــه املتفــق عليــه وقيامــه بإقامــة هــذه الدعــوى‬\n      ‫االســتباقية بقصــد األضــرار والكيــد والنيــل منــي وعــدم مطالبتــي‬\n      ‫بحقوقــي املترتبــة علــى فســخ العقــد جتاهــه وإهــدار املســتحق لــي مــن‬\n      ‫أتعــاب‪ ،‬وكمــا يقــول الفقهــاء أن اللجــوء للتقاضــي ليــس مطلق ـ ًا وإمنــا‬\n      ‫هــو مقيــد بــأال يكــون اســتعماله لهــذا احلــق بطريقــة غيــر مشــروعة‬\n\n\n‫‪281‬‬\n\f‫تلحــق أضــرار ًا بالغيــر ألنــه ممنــوع مــن التعســف يف اســتعمال أي حــق مــن‬\n‫احلقــوق التــي تثبــت لــه فــا يجــوز اســتخدام حــق التقاضــي بقصــد‬\n‫اإلســاءة أو الكيــد أو مضايقــة اخلصــم جنــد أن دعــواه هــذه دعــوى‬\n‫اســتباقيه الغــرض منهــا االلتفــاف حــول مــا يتوجــب الوفــاء بــه وهــو‬\n‫أتعابــي ‪.‬الوجــه األول ‪-:‬ملــا ورد باملــادة الرابعــة مــن عقــد األتعــاب والــذي‬\n‫ورد فيــه ( يســتحق الطــرف األول كامــل األتعــاب املشــار إليهــا يف البنــد‬\n‫الثالــث يف حــال فســخ الطــرف الثانــي الوكالــة الشــرعية أو إنهــاء‬\n‫موضــوع الدعــوى مــع املدعــي صلحــا ‪ ،‬أو حــال طلــب الطــرف الثانــي (‬\n‫املدعــي يف هــذه الدعــوى ) إيقــاف الطــرف األول عــن االســتمرار يف‬\n‫الدعــوى ) (مرفــق رقــم ‪ )1‬باإلطــاع علــى اخلطــاب (‪ ) 520‬بتاريــخ‬\n‫‪1432/08/02‬ه ـ جنــد أن جميــع التزاماتــي التعاقديــة متــت لصالــح‬\n‫املدعــى فعليــا دون إهمــال او تقصيــر وبعــد ذلــك قــام املدعــي وبــدون‬\n‫ســابق إنــذار بإخطــاري بفســخ عقــد األتعــاب مــن طرفــه فقــط دون أدنــى‬\n‫تقصيــر او إهمــال ‪.‬الوجــه الثانــي ‪-:‬ورد يف البنــد ســابعا (التزامــات‬\n‫الطــرف الثانــي ) مــا يلــي ( يلتــزم عــدم إخفــاء أي وقائع مؤثرة يف الدعوى‬\n‫او نقــل شــيء للطــرف األول خــاف احلقيقــة ‪ ...‬الــخ ) ومــع ذلــك خالــف‬\n‫املدعــي هــذا البنــد عندمــا أخفــى انخصمــه واملدعــو ‪ ................. /‬لــم‬\n‫يقــم باتخــاذ أي إجــراءات نظاميــة يف العقــد احملــرر بينهمــا لصاحلــه وقــد‬\n‫ذكــر لــي ذلــك يف أكثــر مــن اجتمــاع و قــام قبــل موعــد اجللســة بيومــن‬\n‫فقــط وأرســل خطابــه رقــم ‪/5‬ص‪111006/‬يفيــد ان خصمــه قــد قــام‬\n‫بالفعــل باتخــاذ إجــراءات نظاميــة فعليــه وقــد وافقــت أمانــة جــدة لــه علــى‬\n‫ان اشــتراطات املشــاريع اخلاصــة باملدعــي اســتتباعا التخــاذ باقــي‬\n‫اإلجــراءات ‪ ،‬وهــو بذلــك عندمــا ســلمنا هــذا اخلطــاب املرفــق قــد نســي‬\n\n\n                                                                                       ‫‪282‬‬\n\f      ‫انــه ذكــر لنــا ســابقا ان خصمــه لــم يقــم باتخــاذ أي إجــراءات لصاحلــه‬\n      ‫ويف ذلــك إخفــاء ملعلومــات قــد تغيــر لنــا وجــه الســير يف دعــواه وقــد‬\n      ‫خالــف بذلــك البنــد الســابع املنــوه عنــه لفضيلتكــم وحيــث مت إفهامــه‬\n      ‫بعــدم إخفــاء أي معلومــات مبوجــب خطابنــا رقــم (‪ )799‬وتاريــخ‬\n      ‫‪1432/12/23‬ه ــوقد اســتدرك ذلــك املدعــي وقــام بفســخ العقــد وتقــدم‬\n      ‫باألعــذار الواهيــة لعلمــه التــام انــه قــام بإخفــاء املعلومــات التــي تؤثــر يف‬\n      ‫ســير القضيــة ‪.‬الوجــه الثالــث ‪-:‬ثــم جــاءت املــادة احلاديــة عشــر (حــل‬\n      ‫النزاعــات ) حيــث ورد بهــا مــا يلــي ( عنــد حــدوث أي نــزاع بــن األطــراف‬\n      ‫ال ســمح اهلل يتــم حلــه وديــا ‪ ،‬فــان تعــذر ذلــك يتــم حــل هــذا النــزاع عــن‬\n      ‫طريــق التحكيــم وفقــا لنظــام التحكيــم الســعودي) بإطــاع جنــد انــه‬\n      ‫حــددت املــادة يف حــال حــدوث نــزاع يحــل بالطــرق الوديــة ‪ -‬إن وجــد‪ -‬إال‬\n      ‫ان املدعــي قــام برفــع الدعــوى بــدون ســابق إنــذار لــي وهنــا يتضــح ســوء‬\n      ‫نيــة املدعــي فــكان يتوجــب علــى املدعــي قبــل إجــراء فســخ العقــد أن‬\n      ‫يتبــع الطــرق الوديــة ويبــدي اخلــاف _ إن وجــد _ أمــا وانــه بــدون ســابق‬\n      ‫إنــذار وال يوجــد باألســاس أي خــاف بينــي وبــن املدعــي وهنــا يثبــت إن‬\n      ‫الدعــوى املقامــة مــن املدعــي هــي اســتباقية حتــى ال أتقــدم بدعــوى‬\n      ‫قضائيــة ويتــم إلزامــه مبؤخــر االتعــاب واملشــار اليــه باملــادة مــن عقــد‬\n      ‫األتعــاب رابعــا ‪ -:‬فيمــا يتعلــق بإجــراء فســخ عقــد االتعــاب مــن قبــل‬\n      ‫املدعــى وبالنظــر الــى الدعــوى جنــد ان املدعــي قــد خاطبنــي مبوجــب‬\n      ‫خطابــه املرفــق بهــذه املذكــرة يخطرنــي فيــه بفســخ العقــد مرجعــا ذلــك‬\n      ‫ألســباب غيــر صحيحــة ومــردود عليهــا ‪ ،‬فقــد ذكــر يف خطــاب الفســخ‬\n      ‫البنــد االول منــه أنــه ُ طلــب حضــوره إلــى شــرطة جــدة ولكنــي لــم أحضــر‬\n      ‫وردي علــى ذلــك هــو عــدم صحــة مــا ذكــره املدعــي وهنــا فإننــي أطلــب‬\n\n\n‫‪283‬‬\n\f‫منــه البينــة علــى ذلــك والصحيــح انــه لــم يتــم إبالغــي رســميا بطلــب‬\n‫احلضــور الــى شــرطة جــدة بــل تلقيــت مكاملــة هاتفيــة مــن متصــل افهمني‬\n‫فيهــا ان هنــاك شــكوى قُ دمــت ضــد شــرطة الشــرفية وإدارة البحــث‬\n‫مــن خصــم املدعــي يف الدعــوى األصليــة فذكــرت للمتصــل مــا عالقــة‬\n‫موكلــي املدعــي بهــذه الشــكوى ومــع ذلــك وحرصــا منــي علــى الدفــاع‬\n‫عــن املدعــي قمــت برفــع اســتدعاء الــى محافظــة جــدة قيــد حتــت رقــم‬\n‫(‪ )3220241837‬وتاريــخ ‪1432/10/21‬ه ـ فهــل بذلــك اكــون قــد‬\n‫قصــرت كمــا يدعــي املدعــي يف دعــواه ‪ ،‬أمــا مــا ذكــره بــان هنــاك‬\n‫التزامــات يجــب ان احتملهــا يف الدفــاع عــن موكلــي فهــذا صحيــح‬\n‫ولكــن فيمــا يخــص الدعــوى املتعاقــد عليهــا ومــا يتفــرع مــن اصلهــا‬\n‫وليــس أي دعــوى جديــدة تقــام ضــده ومليتــم التعاقــد معــي بشــأنها أمــا مــا‬\n‫ذكــره يف خطــاب الفســخ البنــد الثانــي فغيــر صحيــح وادعــاء باطــل مــن‬\n‫قبــل املدعــي فهــو يتهمنــي باإلهمــال والتقصيــر وخــرق للبنــد اخلامــس مــن‬\n‫العقــد وهــذا مــردود عليــه ايضــا فقــد خاطبــت املدعــي مبوجــب اخلطــاب‬\n‫رقــم (‪ ) 520‬وتاريــخ ‪1432/08/02‬ه ـ املتضمــن ســحب امللــف مــن‬\n‫احملكمــة ‪ ،‬وقمــت بعدهــا مبتابعــة مبراجعــه مكتــب القاضــي ‪،.......‬‬\n‫ـاء علــى طلــب وكيــل‬  ‫والــذي أفادنــي ان املعاملــة صــدرت لشــرطه جــده بنـ ً‬\n‫محافــظ جــدة فقامــت احملكمــة بإرســال كامــل املعاملــة الــي الشــرطة‬\n‫لنســخ صــورة منهــا ‪ ،‬وحينهــا قمــت بتقــدمي اســتدعاء الــى محافــظ جــدة‬\n‫بشــان إعتــراض ســحب امللــف مــن احملكمــة وقيــد ذلــك حتــت رقــم‬\n‫(‪ )32202412104‬وكان نتيجــة ذلــك ان ارســلت محافظــة جــدة امللــف‬\n‫مــرة اخــرى للمحكمــة وحــدد جلســة بعدهــا لنظــر الدعــوى فكيف إذن‬\n‫يكــون التقصيــر‪ ،‬علمــا بأنــه قــد خاطبــت املدعــي مبوجــب خطابــي‬\n\n\n                                                                                     ‫‪284‬‬\n\f      ‫املنــوه عنــه بــكل هــذه التفاصيــل اال انــه تناســى بغيــة إحلــاق الضــرر بــي‬\n      ‫ومــن ناحيــة مــا ذكــره املدعــي يف خطــاب الفســخ والــذي يــدل علــى ســوء‬\n      ‫النيــة وال يســتند إلــى مبــرر شــرعي أو نظامــي وذلــك عندمــا يدعــي علــى‬\n      ‫خــاف احلقيقــة اننــي لــم أحضــر اجللســة احملــدد لهــا ‪1432/12/17‬ه ـ‬\n      ‫فهــذا تصــور مــن وحــي خيالــه ينــايف ويجــايف الواقــع ومــردود عليــه‬\n      ‫والصحيــح أننــي حضــرت باملوعــد احملــدد ومت إفهامــي بعــدم انعقــاد‬\n      ‫اجللســة لكــون انتقــال الشــيخ ‪ .................... /‬إلــى محكمــة اخــرى ‪،‬‬\n      ‫فهــل يســتقيم أن أحضــر جلســة لــم تعقــد أساســا ويقــوم املدعــي‬\n      ‫مبحاســبتي عــن عــدم احلضــور ‪ ،‬وإن دل فإنــه يــدل أن حجــة املدعــي ال‬\n      ‫أســاس لهــايف هــذه الدعــوى بغيــة إكســاب نفســه بعــض احلقــوق التــي ال‬\n      ‫وجــود لهــا أساســا ‪ ،‬فقــد خاطــب املدعــي بــكل هــذه التفاصيــل مبوجب‬\n      ‫خطابي الذي يحمل رقم ‪/111‬ص ع‪ 33 /‬وتاريخ ‪1433 /01 /25‬هـومع‬\n      ‫ذلــك يتعنــت يف إقامــة هــذه الدعــوى ضــدي دون ســند او دليــل بغيــة‬\n      ‫اهــدار حقــي مــن قبلــه‪ .‬خامسـ ًا ‪ -:‬مخالفــة دعوى املدعي لنظــام احملاماة‬\n      ‫والــذي هــو املرجــع النظامــي لعقــد األتعــاب بــن الطرفــن ‪.‬ملــا كنــت‬\n      ‫وكيــا شــرعي ًا وهنــاك نظــام مقــن ومعمــول بــه ينظــم العالقــة بــن كل‬\n      ‫محامــي والوكيــل او وموكلــه وحيــث أن القاعــدة ( ال اجتهــاد مــع‬\n      ‫نــص) هنــا يتوجــب تأســيس احلكــم علــى نظــام احملامــاة وليــس علــى‬\n      ‫اجتهــادات املدعــي وال اجتهــاد مــع نــص كمــا ذكــر ‪ ،‬ولكــن‬\n      ‫االجتهــادات الشــرعية التــي جتــري يف الدعــوى مشــروطة بتحقيــق العدل‬\n      ‫بــن طــريف التداعــي ‪ ،‬فــإذا خــا احلكــم مــن هــذا التســبيب والتأصيــل‬\n      ‫يكــون حكم ـ ًا غيــر مالقي ـ ًا للدعــوى‪ .‬عنــد تطبيــق هــذا النــزاع علــى‬\n      ‫نظــام احملامــاة ا ُملعــول عليــه أساســا مســألة الفصــل يف اخلــاف بــن‬\n\n\n‫‪285‬‬\n\f‫الوكيــل وموكلــه جنــد أن املادتــن السادســة والعشــرين والســابعة‬\n‫والعشــرين أوضحــت حــا كاشــفا ملــا بــدر يف هــذه الدعــوى لفضيلــة‬\n‫حاكمهــا وتفســير ذلــك يأتــي حســب مــا يــرد مــن نصــوص علــى النحــو‬\n‫التالــي حيــث قــررت املــادة (‪ )27‬مــن نفــس النظــام لتقــرر ( للمــوكل أن‬\n‫يعــزل محاميــه‪ ،‬وعليــه أن يدفــع كامــل األتعــاب املتفــق عليهــا إذا ثبــت‬\n‫أن العزل‪-‬بســبب غيــر مشــروع‪ ،‬مــا لــم تــر احملكمــة املختصــة بنظــر‬\n‫القضيــة غيــر ذلــك بالنســبة للعــزل وكامــل األتعاب ) وهنا يبدر الســؤال‬\n‫عــن ماهيــة الســبب املشــروع الــذي مــن أجلــه قــام املدعــى بفســخ عقــد‬\n‫األتعــاب احملــرر معــي ‪ -‬واإلجابــة تتضــح لفضيلتكــم بوضــوح يف هــذه‬\n‫الدعــوى أال وهــي محاولــة املدعــي التنصــل مــن التزاماتــه التعاقديــة مــن‬\n‫قبلــي دون مبــرر ودون ســبب مشــروع ‪ .‬صاحــب الفضيلــة وترتيبــا علــى‬\n‫مــا تقــدم فإننــي أطلــب ‪ -:‬صــرف النظــر عــن دعــوى املدعــي اســتنادا إلــى‬\n‫مــا ذكرنــا مــن أســباب نظاميــة بصــدر هــذه املذكــرة ومــا قــد يتــراءى‬\n‫لفضيلتكــم اثنــاء بحــث ودراســة ملــف الدعــوى ا‪.‬ه ـ ‪ ،‬ثــم جــرى ســؤال‬\n‫الطرفــن عــن عقــد اإلتفــاق فأجــاب املدعــي بــأن هنــاك صــورة منــه يف‬\n‫املعاملــة وبعرضهــا علــى املدعــى عليــه أجــاب بقولــه نعــم هــذا هــو العقــد‬\n‫املبــرم مــع املدعــي وباإلطــاع عليــه وجــد محررا علــى مطبوعات مكتب‬\n‫‪ ...............‬ومشــار للمكتــب املذكــور وميثلــه املدعــى عليــه يف هــذه‬\n‫الدعــوى بالطــرف األول ومشــار للمدعــي بالطــرف الثانــي ومتضمنــا‬\n‫اإلتفــاق بــن الطرفــن علــى اثنــي عشــر بنــدا ومســبوق بتمهيــد وباإلطالع‬\n‫عليــه وجــد يف نــص الفقــرة احلاديــة عشــرة منــه مــا نصــه « حــل النزاعــات‪:‬‬\n‫عنــد حــدوث أي نــزاع يتــم حلــه وديــا فــإن تعــذر ذلــك يتــم حــل هــذا النــزاع‬\n‫عــن طريــق التحكيــم وفقــا للنظــام التحكيــم الســعودي ويكــون‬\n\n\n                                                                                         ‫‪286‬‬\n\f      ‫بالرجــوع للجنــة التحكيــم بالغرفــة التجاريــة الصناعيــة بجــدة ويكــون‬\n      ‫قــرار التحكيــم نهائيــا وملزمــا لألطــراف ويتــم تنفيــذه فــورا بــدون‬\n      ‫اللجــوء أليــة إجــراءات قضائيــة أو إداريــة أخــرى « أ‪.‬ه ـ نــص املــادة وبنــاء‬\n      ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة ونظــرا ملــا جــاء يف املــادة الثانيــة‬\n      ‫عشــرة مــن العقــد واملرصــود نصهــا بعاليــه ومبــا أن مــا اتفــق عليــه‬\n      ‫الطرفــان ملــزم لهمــا بقــوة العقــد الــذي اتفقــا عليــه ونظــرا ملــا ورديف‬\n      ‫نظــام التحكيــم الصــادر باملرســوم امللكــي رقــم م‪ 34/‬وتاريــخ‬\n      ‫‪1433/5/24‬ه ـ يف املــادة التاســعة منــه حيــث جــاء يف نصهــا يف الفقــرة‬\n      ‫(أ) يجــوز أن يكــون اتفــاق التحكيــم ســابقا علــى قيــام النــزاع ســواء‬\n      ‫أكان مســتقال بذاتــه أم ورد يف عقــد معــن ‪ ..‬الــخ ‪ ،‬كمــا جــاء يف‬\n      ‫الفقــرة (‪ )3‬مــن نفــس املــادة مــا نصــه ‪ « :‬يكــون إتفــاق التحكيــم‬\n      ‫مكتوبـ ًا إذا تضمــن محــرر صــادر مــن طــريف التحكيــم أو إذا تضمنــه‬\n      ‫مــا تبــاداله مــن مراســات موثوقــة أو برقيــات أو غيرهــا مــن وســائل‬\n      ‫االتصــال اإللكترونيــة أو املكتوبــة وتعــد اإلشــارة يف عقدها أو اإلحالة‬\n      ‫فيــه إلــى مســتند يشــتمل علــى شــرط التحكيــم مبثابــة اتفــاق حتكيــم‪..‬‬\n      ‫الــخ وبنــاء عليــه وملــا اشــتمل عليــه العقــد بــن الطرفــان مــن النــص علــى‬\n      ‫اإلحالــة إلــى التحكيــم عنــد حــدوث أي نــزاع لــذا فقــد قــررت صــرف‬\n      ‫النظــر عــن دعــوى املدعــي كمــا قــررت صــرف النظــر عــن مــا طلــب‬\n      ‫املدعــى عليــه وجــرى إفهامهمــا بأنــه يلزمهمــا إجــراء التحكيــم وفقــا ملــا‬\n      ‫اتفقــا عليــه وبذلــك حكمــت وبعرضــه عليهمــا قــرر املدعــي عــدم‬\n      ‫القناعــة وقــرر املدعــى عليــه عــدم القناعــة فجــرى افهامهمــا مبــا تقتضيه‬\n      ‫املــواد ‪ 178/176‬مــن نظــام املرافعــات الشــرعية ففهمــا ذلــك‪ ،‬حتــى ال‬\n      ‫يخفــى ‪ ،‬وبــاهلل التوفيــق ‪،‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه‬\n\n\n‫‪287‬‬\n\f                                                              ‫وصحبه وسلم ‪،،‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪،‬‬\n‫فقــد جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة‬\n‫االســتئناف يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة املســاعد مبحافظــة جــدة برقــم‬\n‫‪331697472‬وتاريــخ ‪1434/4/21‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــة الشــيخ ‪...................‬القاضــي باحملكمــة العامــة مبحافظــة‬\n‫جــدة برقــم ‪ 3461567‬وتاريــخ ‪ 1434/3/14‬ه ـ ‪،‬املتضمــن دعــوى‬\n‫‪ .....................‬ضــد ‪ .............................‬وبدراســة الصــك وصــورة ضبطــه‬\n‫والئحتــه االعتراضيــة تقــرر املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى‬\n                ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                           ‫‪288‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":276,"source_page_end":288,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"527991919fe44e1eb28780a62662210fa19413554bdbc6c1432ecc080f3972db","normalized_text_hash":"527052334253b60f046dde847357e02f82bdc60a111789cd74fa9bf3bab5259f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p276-3461567"},{"id":"777d6b16-0eda-5483-b7ae-d3df64a099a5","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -عماله منزليه -أجرة عمل -مطالبة خادمة منزلية بباقي رواتبها -دفع املدعى عليه بحسم ما أتلفته املدعية من راتبها -ميني املدعية على نفي اإلتاف والتعدي -األجير اخلاص ال يضمن إال أن يتعدى -احلكم بتسليم املدعية باقي رواتبها بعد خصم قيمة اجلوال وشريحته.","document_number":"34546","case_number":"33580289","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية على املعاملة الواردة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/3","year":"1434","subject":"عقد -عماله منزليه -أجرة عمل -مطالبة خادمة منزلية بباقي رواتبها -دفع املدعى عليه بحسم ما أتلفته املدعية من راتبها -ميني املدعية على نفي اإلتاف والتعدي -األجير اخلاص ال يضمن إال أن يتعدى -احلكم بتسليم املدعية باقي رواتبها بعد خصم قيمة اجلوال وشريحته.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"         ‫رقم الصك‪ 34546 :‬تاريخه‪1434/1/3 :‬هـ‬\n                        ‫رقم الدعوى‪33580289 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34188598‬تاريخه‪1434/4/15 :‬هـ‬\n\n\n      ‫عقــد ‪ -‬عمالــه منزليــه ‪ -‬أجــرة عمــل ‪ -‬مطالبــة خادمــة منزليــة بباقــي‬\n      ‫رواتبهــا‪ -‬دفــع املدعــى عليــه بحســم مــا أتلفتــه املدعيــة مــن راتبها‪ -‬ميني‬\n      ‫املدعيــة علــى نفــي اإلتــاف والتعــدي‪ -‬األجيــر اخلــاص ال يضمــن إال‬\n      ‫أن يتعــدى ‪ -‬احلكــم بتســليم املدعيــة باقــي رواتبهــا بعــد خصــم قيمــة‬\n                                                               ‫اجلــوال وشــريحته‪.‬‬\n\n\n\n\n      ‫جــاء يف املبــدع شــرح املقنــع (‪{ :)445/4‬وال ضمــان علــى األجيــر اخلــاص‬\n      ‫نــص عليــه وهــو الــذي يســلم نفســه إلــى املســتأجر أي يقــع عليــه العقــد‬\n      ‫مــدة معلومــة يســتحق املســتأجر نفعــه يف جميعهــا } إلــى قولــه { ألن‬\n      ‫عملــه غيــر مضمــون عليــه فلــم يضمــن مــا تلــف بــه كالقصــاص‬\n      ‫وألنــه نائــب عــن املالــك يف صــرف منافعــه فيمــا أمــر بــه فلــم يضمــن‬\n           ‫كالوكيــل إال أن يتعــدى ألنــه تلــف بتعديــه أشــبه الغاصــب}‪.‬‬\n\n\n\n\n      ‫ا لهــا‪،‬‬\n             ‫ادعــت املدعيــة أنهــا عملــت عنــد املدعــى عليــه وكان كفي ـ ً‬\n      ‫وبقــي مــن رواتبهــا أربعــة آالف ومائــة ريــال وطلبــت إلزامــه بتســليمها‬\n      ‫هــذا املبلــغ ‪ -‬بعــرض الدعــوى علــى املدعــى عليــه صــادق عليهــا‪ ،‬ودفــع‬\n      ‫أنــه حســم املبلــغ املذكــور مــن رواتبهــا ألنهــا أتلفــت فــرن كهربائــي‬\n\n‫‪289‬‬\n\f‫ثمنــه ‪2200‬ريــال و أتلفــت عباءتــن وهــي تكويهمــا‪ ،‬كمــا أنــه اشــترى‬\n‫لهــا شــريحة جــوال مبائــة ريــال‪ ،‬وقــرر أنــه غيــر مســتعد بتســليم هــذا‬\n‫املبلــغ لهــا‪ -‬بعــرض دفــع املدعــى عليــه علــى املدعيــة أنكــرت إتــاف‬\n‫الفــرن‪ ،‬وأمــا العباءتــن فبســبب نوعيــة قمــاش العبــاءة ظهــر لــون أبيــض‬\n‫أثنــاء الكــوي يف طــرف العبــاءة جهــة الــزرار‪ ،‬ولــم تتلــف العباءتــن ولــم‬\n‫تتعمــد ذلــك‪ ،‬كمــا قــررت أنــه ال مانــع لديهــا مــن حســم املائــة ريــال ثمــن‬\n‫الشــريحة و اجلــوال ‪ -‬بطلــب البينــة مــن املدعــي علــى قيــام املدعــى عليــه‬\n‫باالتــاف عمــد ًا قــرر أنــه ليــس لديــه بينــة علــى ذلــك وطلــب ميــن املدعــى‬\n‫عليهــا علــى نفــي ذلــك ‪ -‬اســتعدت املدعيــة ببــذل اليمــن‪ ،‬ثــم حلفتهــا ‪-‬‬\n‫كــون املدعيــة تعمــل لــدى املدعــى عليــه عاملــة منزليــة أجيــرة خاصــة‪،‬‬\n‫واألجيــر اخلــاص ال يضمــن إال أن يتعــدى ‪ -‬املدعــى عليــه ليــس لديــه بينــة‬\n‫علــى اإلتــاف أص ـاً‪ ،‬فضــا علــى أن يكــون لديــه بينــة علــى التعــدي‬\n‫‪ -‬املدعيــة حلفــت اليمــن ‪ -‬املدعيــة أقــرت مبائــة ريــال ثمــن شــريحة‬\n‫وجهــاز جــوال وقــررت عــدم املمانعــة بحســمها ‪ -‬لــذا مت احلكــم علــى‬\n‫املدعــى عليــه أن يســلم للمدعيــة أربعــة آالف ريــال حــاال باقــي رواتبهــا‬\n‫وعــدم اســتحقاق املدعيــة مــا زاد عــن هــذا املبلــغ وهــو مائــة ريــال الــذي‬\n‫أقــرت أنــه ثمــن شــريحة و جهــاز جــوال ‪ -‬بعــرض احلكــم عليهمــا قــررت‬\n‫املدعيــة القناعــة بــه و قــرر املدعــى عليــه عــدم القناعــة وطلــب اســتئناف‬\n‫احلكــم ‪ -‬بعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......................‬القاضــي يف احملكمــة‬\n‫اجلزائيــة باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n\n                                                                                       ‫‪290‬‬\n\f      ‫احملكمــة اجلزائيــة يف محافظــة اخلبــر برقــم ‪ 33580289‬وتاريــخ‬\n      ‫‪ 1433/09/18‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331724602‬وتاريــخ‬\n      ‫‪ 1433/09/18‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1433/12/21‬هـ افتتحت‬\n      ‫اجللســة الســاعة ‪ 09 : 00‬وفيهــا حضــر حضــرت ‪ ...............‬أندونســية‬\n      ‫اجلنســية مبوجــب رخصــة االقامــة رقــم (‪ )...............‬و املعــرف بهــا مــن‬\n      ‫قبــل ‪ ......................‬ســجله (‪ )..................‬و حضــر حلضورهــا ‪.................‬‬\n      ‫ســعودي اجلنســية ســجله املدنــي رقــم (‪ )...............‬وادعــت األولــى علــى‬\n      ‫الثانــي قائلــة إن املدعــى عليــه كان كفيلــي الســابق قبــل نقــل كفالتــي‬\n      ‫إلــى كفيلــي احلالــي و بقــي لــي مــن رواتبــي ‪4100‬ريــال اطلــب ســؤاله‬\n      ‫اجلــواب و احلكــم عليــه بســداد املبلــغ كامــا هــذه دعــواي وبعــرض‬\n      ‫ذلــك علــى املدعــى عليــه اجــاب قائــا مــا ذكرتــه املدعيــة صحيــح وقــد‬\n      ‫خصمــت عليهــا ‪ 4100‬ريــال وذلــك ألنهــا أتلفــت فــرن كهربائــي ثمنــه‬\n      ‫‪2200‬ريــال وأتلفــت عبايتــن وهــي تكويهمــا و اشــتريت لهــا شــريحة‬\n      ‫جــوال مبائــة ريــال و غيــر مســتعد بســداد املبلــغ هــذه دعــواي وبــرد ذلــك‬\n      ‫للمدعيــة قــررت قائلــة مــا ذكــره املدعــى عليــه غيــر صحيــح فلــم أتلــف‬\n      ‫الفــرن و بالنســبة للعبايتــن فكنــت أكويهمــا وبســبب نوعيــة قمــاش‬\n      ‫العبايــة ظهــر لــون أبيــض يف طــرف العبــاءة جهــة الــزرار لكــن لــم تتلــف‬\n      ‫العبايتــن ولــم اتعمــد و املائــة ريــال ثمــن الشــريحة و اجلــوال فــا مانــع‬\n      ‫مــن خصمهــا هــذا وبطلبــي مــن املدعــى عليــه البينــة علــى قيــام املدعيــه‬\n      ‫بإتــاف الفــرن والعبائتــن عمــدا قــال ليــس لــدي البينــة علــى ذلــك‬\n      ‫فجــرى إفهامــه بــأن لــه ميينهــا علــى عــدم االتــاف و عــدم التعــدي فقــال‬\n      ‫اطلــب ميينهــا هــذا وبســؤال املدعيــة عــن اســتعداها بــأداء اليمــن قالــت‬\n      ‫إننــي مســتعدة بــأداء اليمــن هكــذا قــررت فأذنــت لهــا فحلفــت قائلــة‬\n\n\n‫‪291‬‬\n\f‫واهلل العظيــم أننــي لــم أتلــف الفــرن ولــم أتلــف العبايتــن و واهلل إن مــا‬\n‫حلــق العبايتــن أثنــاء الكــوي ال يفســدهما ولــم أتعمــد ظهــور البيــاض‬\n‫جهــة الــزرار هكــذا حلفــت فبنــاء علــى مــا تقــدم مــن الدعــوى و اإلجابــة‬\n‫وحيــث أن املدعيــة كانــت تعمــل لــدى املدعــى عليــه عاملــة منزليــة‬\n‫أجيــرة خاصــة فوقتهــا مملــوك لــه وحيــث إن األجيــر اخلــاص ال يضمــن‬\n‫إال أن يتعــدى جــاء يف كتــاب املبــدع شــرح املقنــع ج ‪ 4‬صفحــة ‪{ 445‬وال‬\n‫ضمــان علــى األجيــر اخلــاص نــص عليــه وهــو الــذي يســلم نفســه إلــى‬\n‫املســتأجر أي يقــع عليــه العقــد مــدة معلومــة يســتحق املســتأجر نفعــه يف‬\n‫جميعهــا} إلــى قولــه { ألن عملــه غيــر مضمــون عليــه فلــم يضمــن مــا تلــف‬\n‫بــه كالقصــاص وألنــه نائــب عــن املالــك يف صــرف منافعــه فيمــا أمــر بــه‬\n‫فلــم يضمــن كالوكيــل إال أن يتعــدى ألنــه تلــف بتعديــه أشــبه الغاصــب‬\n‫( و حيــث إن املدعــى عليــه ليــس لديــه بينــة علــى االتــاف أصــا فضــا‬\n‫علــى أن يكــون لديــه بينــة علــى التعــدي و حيــث جــرى إفهــام املدعــى‬\n‫عليــه أن لــه ميــن املدعيــة علــى نفــي االتــاف و التعــدي فقــرر طلب اليمني‬\n‫وحيــث حلفــت املدعيــة علــى طبــق طلــب املدعــى عليــه لــذا وحيــث أقــرت‬\n‫املدعيــة مبائــة ريــال ثمــن شــريحة وجهــاز جــوال وقــررت عــدم املمانعــة‬\n‫بخصــم مائــة ريــال لــذا حكمــت علــى املدعــى عليــه بــأن يدفــع للدعيــة‬\n‫أربعــة آالف ريــال حــاال باقــي رواتبهــا وحكمــت بعــدم اســتحقاقها مــا‬\n‫زاد عــن هــذا املبلــغ وهــو مائــة ريــال الــذي أقــرت أنــه ثمــن شــريحة و‬\n‫جهــاز جــوال وبعــرض احلكــم عليهمــا قــررت املدعيــة القناعــة بــه و قــرر‬\n‫املدعــى عليــه عــدم القناعــة وطلــب اســتئناف احلكــم فأجبتــه لطلبــه و‬\n‫أفهمتــه بتعليمــات االســتئناف وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n                      ‫نبينــا محمــد والــه وصحبــه ‪ .‬حــرر يف ‪1433/12/21‬ه ـ‬\n\n\n                                                                                    ‫‪292‬‬\n\f      ‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n      ‫أمــا بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى يف‬\n      ‫محكمة االســتئناف باملنطقة الشــرقية على املعاملة الواردة من فضيلة‬\n      ‫رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم ‪ 33/1724602‬وتاريــخ‬\n      ‫‪1434/3/2‬ه ـ واملقيــدة لدينــا برقــم ‪ 34581423‬وتاريــخ ‪1434/3/7‬ه ـ‬\n      ‫املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪/‬‬\n      ‫‪ .........................‬املسـ ّـجل برقــم ‪ 34546‬وتاريــخ ‪1434/1/3‬ه ـ اخلــاص‬\n      ‫بدعــوى‪( ............./‬أندونيســية اجلنســية) ضــد‪ .............../‬يف قضيــة‬\n      ‫حقوقيــة وقــد تضمــن القــرار حكــم فضيلته مبا هو مــدون ومفصل فيه‪.‬‬\n      ‫وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n      ‫قررنــا املصادقــة علــى احلكــم ‪ ،‬ولبيانــه حــرر يف ‪1434/4/15‬هــ‪ ،‬واهلل‬\n                                                                       ‫ولــي التوفيــق‪.‬‬\n\n\n\n\n‫‪293‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":289,"source_page_end":293,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7eb1bbb132e1d46e6e02fd49a94d6eeb4ec3458329f8c8c29d68712d491aa9ec","normalized_text_hash":"7c2af3d8aec2915e4dc070ca55b6601f6591aea19d8b7d7ded7c731a914ae5f9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p289-34546"},{"id":"30f17325-f709-5cc9-aa4a-061b69d2cdd9","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة بأتعاب محاماة -محل األتعاب دعوى قسمة تركه - الدعوى ما زالت منظورة -وقف النظر يف الدعوى وتعليق احلكم على الفصل يف الدعوى األصلية.","document_number":"34279057","case_number":"33684889","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة القطيف ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/25","year":"1434","subject":"مطالبة بأتعاب محاماة -محل األتعاب دعوى قسمة تركه - الدعوى ما زالت منظورة -وقف النظر يف الدعوى وتعليق احلكم على الفصل يف الدعوى األصلية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34279057:‬تاريخه‪1434/7/25:‬هـ‬\n                  ‫رقم الدعوى‪33684889:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 34385440‬تاريخه‪1434/12/23 :‬هـ‬\n\n\n‫مطالبــة بأتعــاب محامــاة ‪ -‬محــل األتعــاب دعــوى قســمة تركــه ‪-‬‬\n‫الدعــوى مــا زالــت منظــورة ‪ -‬وقــف النظــر يف الدعــوى وتعليــق احلكــم‬\n                                  ‫علــى الفصــل يف الدعــوى األصليــة‪.‬‬\n\n\n\n\n                                     ‫املادة ‪ 83‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليهــن بأنــه قــد مت توكيلــه مــن قبــل املدعــى‬\n‫عليهــن للترافــع وقــدمت فســخ وكالتــه قبــل صــدور احلكــم يف القضيــة‬\n‫وأثنــاء نظرهــا وهــذا مخالــف للبنــد الســابع مــن اتفاقيــة أتعــاب احملامــاة‬\n‫وقــد حضــر أكثــر مــن ســت جلســات وبــذل اجلهــد والدفــع الذيــن عــاد‬\n‫عليهــم بالنفــع األمــر الــذي جعــل وكيــل الورثــة املدعــو‪ ... /‬وهــو مــن‬\n‫وكلــه عــن املدعــى عليهــم ‪ ،‬بــأن يلجــأ إلــى أســلوب الغــدر حــن أوعــز‬\n‫للورثــة املذكوريــن بفســخ وكالتهــم لــه وذلــك لكــون وكالتــه صــادرة‬\n‫عنــه ممــا يجعــل وكالــة املدعــي الغيــة بالتبعيــة ونســبة أتعــاب املدعــي‬\n‫هــي ‪ %20‬مــن إجمالــي مــا يحكــم بــه من مبلغ التركة املقدرة ب ــخمسني‬\n‫مليــون ريــال ليصبــح نصيــب األربــع اإلنــاث املدعــى عليهــن والــذي مثلهــن‬\n‫املدعــي مــن امليــراث هــو مبلــغ وقــدره (‪ )10,290,000‬ريــال أي أن املبلــغ‬\n\n                                                                                     ‫‪294‬‬\n\f      ‫املســتحق للمدعــي وواجــب الدفــع هــو (‪ )2,048,000‬ويطلــب تفعيــل‬\n      ‫املــادة (‪ )3/30‬مــن نظــام املرافعــات الشــرعية وذلــك بحــق املدعــو‪.. /‬‬\n      ‫ملــا أحلقــه بــه مــن ضــرر (عنــوة) جــراء مــا قــام بــه مــن غــدر مت علــى أثــره‬\n      ‫فســخ وكالــة املدعــي ويطلــب احلكــم عليــه بالتعزيــر ليكــون رادعـ ًا لــه‬\n      ‫وإلــزام املدعــى عليهــم بدفــع مســتحقاته مببلــغ وقــدره (‪)2،048،000‬‬\n      ‫ريــال هكــذا ادعــى ‪ -‬أجــاب املدعــى عليهــن بعــدم التعاقــد مــع املدعــي‪،‬‬\n      ‫وعــدم االطــاع علــى العقــد الــذي يدعيــه وعــدم التوقيــع عليــه ‪ ،‬وأن‬\n      ‫املدعــي قــد اســتلم منهــن مبلغ ـ ًا نقدي ـ ًا مقــداره خمســون ألــف ريــال‬\n      ‫كمقــدم للترافــع يف القضيــة ولكنــه لــم يقــم بــأي جهــد يذكــر ‪،‬‬\n      ‫وكان يطلــب املهلــة يف عــدة جلســات بــدون الرجــوع إليهــن ‪ ،‬ولــن يدفعــن‬\n      ‫شــيئ ًا مــن املبلــغ املدعــى بــه ‪ -‬أجــاب املدعــي بأنــه تعاقــد مــع وكيــل‬\n      ‫املدعــى عليهــن ‪ ...‬وهــو مخــول يف وكالتــه باإلقــرار والتوقيــع وتوكيــل‬\n      ‫الغيــر ‪ -‬واســتناد ًا للمــادة ‪ 83‬مــن نظــام املرافعــات الشــرعية وألن احلكــم‬\n      ‫ـوكل‬ ‫يف هــذه القضيــة فــرع عــن احلكــم يف القضيــة األصليــة التــي تـ ّ‬\n      ‫فيهــا املدعــي ملــا تقــدم صــدر احلكــم بالتوقــف عــن نظــر القضيــة إلــى‬\n      ‫حــن انتهــاء القضيــة األصليــة املنظــورة بشــأن التركــة ‪ -‬قنــع املدعــى‬\n      ‫عليهــم باحلكــم واعتــرض املدعــي بالئحــة ‪ -‬صــدق احلكــم مــن الدائــرة‬\n                     ‫احلقوقيــة الثانيــة مبحكمــة االســتئناف باملنطقــة الشــرقية ‪.‬‬\n\n\n\n\n      ‫العامــة‬\n         ‫ّ‬     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.........‬القاضــي يف احملكمــة‬\n      ‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫العامــة مبحافظــة القطيــف برقــم ‪ 33684889‬وتاريــخ‬            ‫َ‬    ‫احملكمــة‬\n\n‫‪295‬‬\n\f‫‪1433/11/30‬ه ـ املقيــدة باحملكمــة برقــم ‪ 332158039‬وتاريــخ‬\n‫‪1433/11/30‬ه ـ حضــر املدعــي ‪.........‬ســعودي بالســجل املدنــي رقــم‬\n‫‪.........‬وحضــر حلضــوره املدعــى عليهــم‪ .........‬ســعودية بالســجل املدنــي‬\n‫رقــم ‪.........‬و‪.........‬ســعودي بالســجل املدنــي رقــم ‪.........‬ســعودي بالســجل‬\n‫املدنــي رقــم ‪.........‬و‪ .........‬ســعودي بالســجل املدنــي رقــم ‪.........‬ولــم‬\n‫حتضــر املدعــى عليهــا ‪.........‬وادعــى املدعــي قائ ـاً‪ :‬إعمــا ًال للمــادة‬\n‫(‪ )26‬مــن نظــام احملامــاة واملــادة (‪ )7/11‬مــن نظــام املرافعــات الشــرعية‬\n‫أدفــع بالتالــي‪ :‬أوالً‪ :‬اشــترط البنــد ســابع ًا مــن اتفاقيــة أتعــاب احملامــاة‬\n‫املبرمــة بتاريــخ ‪1433/1/28‬ه ـ مــع املدعــى عليهــم (‪..............................‬‬\n‫‪ ......‬ورثــة ‪ ).........‬مــا نصــه‪ « :‬ال يجــوز للطــرف الثانــي إلغــاء الوكالــة أو‬\n‫ســحب القضيــة مــن الطــرف األول فــإذا فعــل ذلــك التــزم بكامــل أتعــاب‬\n‫الطــرف األول كاملــة وفــور ًا ودون نقــص منهــا» مرفــق رقــم (‪ )1‬كمــا‬\n‫وأرفــق صــور الوكالتــن مرفــق (‪ )2‬و(‪ .)3‬ثاني ـاً‪ :‬قــام املدعــى عليهــم‬\n‫بفســخ الوكالــة أثنــاء نظــر القضيــة مبوجــب صــك فســخ الوكالــة رقــم‬\n‫‪ 33245228‬و رقــم ‪ 33245254‬وتاريــخ ‪1433/8/25‬ه ـ مرفــق رقــم (‪)4‬‬\n‫و (‪ .)5‬ثالث ـاً‪ :‬لقــد حضــرت يف هــذه القضيــة أكثــر مــن ســت جلســات‬\n‫وقــد بذلــت اجلهــد والدفــع الذيــن عــادا علــى موكلينــي بالنفــع حــن بلــغ‬\n‫فضيلتكــم الغايــة مــن البيــان ممــا حــدا بفضيلتكــم إلــى التصريــح‬\n‫بحجــز القضيــة للحكــم األمــر الــذي جعــل وكيــل الورثــة املدعــو‪/‬‬\n‫‪.........‬وهــو مــن وكلنــي عــن الورثــة املذكوريــن ‪ ،‬بــأن يلجــأ إلــى أســلوب‬\n‫الغــدر والتنصــل مــن مــا اشــترطته اتفاقيــة األتعــاب املبرمــة و الواضحــة‬\n‫وامللزمــة حــن أوعــز للورثــة املذكوريــن بفســخ وكالتهــم لــه وذلــك‬\n‫لكــون وكالتــي صــادرة عنــه ممــا يجعــل وكالتــي الغيــه بالتبعيــة ‪،‬‬\n\n\n                                                                                         ‫‪296‬‬\n\f      ‫ظن ـ ًا منــه أنــه يذلــك يســتطيع ســلب مســتحقاتي ال ســيما وأن الفســخ‬\n      ‫وقــع قبــل صــدور احلكــم يف القضيــة وأثنــاء نظرهــا‪ .‬رابع ـاً‪ :‬اشــترط‬\n      ‫البنــد ثالث ـ ًا الفقــرة (‪ )2‬أن قيمــة األتعــاب هــي (‪ )%20‬عشــرون باملائــة‬\n      ‫مــن أجمالــي مــا يحكــم بــه مــن مبلــغ التركــة املقــدرة بــ(‪ )50‬خمســون‬\n      ‫مليــون ريــال ليصبــح نصيــب األربــع اإلنــاث الذيــن أمثلهــم مــن امليــراث هــو‬\n      ‫مبلــغ وقــدره (‪ )10،290،000‬ريــال أي أن املبلــغ املســتحق لــي وواجــب‬\n      ‫الدفــع هــو (‪ )2،048،000‬ريــال‪ .‬خامس ـاً‪ :‬بيــان التركــة التفصيلــي‬\n      ‫املرفــق مت تأسيســه علــى املســتندات الثبوتيــة املرفقــة مرفــق رقــم (‪ )6‬أو‬\n      ‫مســتقاة مــن تقاريــر مت إعدادهــا وتقدميهــا إلــى فضيلــة ناظــر القضيــة من‬\n      ‫قبــل احلــارس القضائــي املهنــدس‪......... /‬وذلــك مبوجــب األمــر القضائــي‬\n      ‫رقــم ‪ 1‬وتاريــخ ‪1433/11/15‬ه ـ بتعيينــه‪ .‬سادسـاً‪ :‬يقتضــي حســن ســير‬\n      ‫العدالــة تفعيــل املــادة (‪ )3/30‬مــن نظــام املرافعــات الشــرعية وذلــك بحــق‬\n      ‫املدعــو‪......... /‬ملــا أحلقــه بــي مــن ضــرر (عنــوة) جــراء مــا قــام بــه مــن غــدر‬\n      ‫مت علــى أثــره فســخ وكالتــي ومبوجبــه أطلــب احلكــم عليــه بالتعزيــر‬\n      ‫ليكــون رادع ـ ًا لــه وعل ـ ــه ألتمــس مــن فضيلتكــم التكــرم باحلكــم‬\n      ‫علــى ورثــة املرحــوم‪......... /‬الــواردة أســمائهم يف الدعــوى بإلزامهــم بدفــع‬\n      ‫ـاء علــى اتفاقيــة األتعــاب املبرمــة مببلــغ وقــدره‬    ‫مســتحقاتي وذلــك بنـ ً‬\n      ‫(‪ )2،048،000‬ريــال هكــذا ادعــى وبعــرض دعــوى املدعــي علــى‬\n      ‫املدعــى عليهــم أجــن قائــات‪ :‬بالنســبة للعقــد فنحــن لــم نتعاقــد مــع‬\n      ‫املدعــي ‪ ،‬ولــم نطلــع علــى العقــد الــذي يدعيــه ولــم نوقــع عليــه ‪ ،‬ونفيــد‬\n      ‫فضيلتكــم بــأن املدعــي قــد اســتلم منــا مبلغ ـ ًا نقدي ـ ًا مقــداره خمســون‬\n      ‫ألــف ريـ(‪ )50.000‬ــال كمقــدم للترافــع يف القضيــة ولكنــه لــم يقــم بأي‬\n      ‫جهد يذكر بل كان يحضر فقط ولم يفدنا بشــيء ولم يكن يشــعرنا‬\n\n\n‫‪297‬‬\n\f‫مبــا يقــع يف جلســات املرافعــة ‪ ،‬وكان يطلــب املهلــة يف عــدة جلســات‬\n‫بــدون الرجــوع إلينــا كمــا أننــا راجعنــا اجلهــات املختصــة فأتضــح لنــا بــأن‬\n‫املدعــي ال يحمــل ترخيصـ ًا ملمارســة احملامــاة ‪ ،‬وحيــث األمــر مــا ذكــر‬\n‫فنحــن غيــر مســتعدات بدفــع مــا يدعيــه هكــذا أجــن فطلــب املدعــي‬\n‫مناقشــة املدعــى عليهــن فناقشــهن ثــم بعــد املناقشــة أضافــت املدعــى‬\n‫عليهــن قائــات‪ :‬إننــا كنــا نعلــم بالعقــد لكننــا ال نعــرف عــن مضمونــه‬\n‫شــيئ ًا ولــم نوقــع عليــه هكــذا أضفــن وقــررن فطلــب املدعــي اإلجابــة‬\n‫عليهــن فأجبتــه لطلبــه فأجــاب قائـاً‪ :‬إننــي تعاقــدت مــع وكيــل املدعــى‬\n‫عليهــن ‪ ....‬وهــو مخــول يف وكالتــه باإلقــرار والتوقيــع وتوكيــل الغيــر‬\n‫ا يف املرافعــة ومتابعــة‬  ‫وقــد بذلــت اجلهــد املطلــوب أثنــاء كونــي وكي ـ ً‬\n‫القضيــة وكنــت أتواصــل مــع وكيــل املدعــى عليهــن ‪......... .........‬‬\n‫وأعطيــه تقريــر ًا دقيقـ ًا بــكل مــا يجــري هكذا أجاب ويف جلســة أخرى‬\n‫حضــر املدعــي وحضــر حلضــوره املدعــى عليــه ‪-.........‬ســعودي بالســجل‬\n‫املدنــي رقــم ‪ -.........‬وكيــا عــن كل مــن ‪ -.........-1‬ســعودية بالســجل‬\n‫املدنــي رقــم ‪-.........-2 -.........‬ســعودية بالســجل املدنــي رقــم ‪-.........‬‬\n‫‪ -.........-3‬ســعودية بالســجل املدنــي رقــم ‪-.........-4 -.........‬ســعودية‬\n‫بالســجل املدنــي رقــم ‪ -.........‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫عــدل القطيــف برقــم ‪ 34603841‬يف ‪1434/05/13‬ه ـ وقبــل أي‬\n‫مناقشــة لهمــا قــدم كل واحــد منهمــا مذكــرة‪ ،‬فاملدعــي قــدم مذكــرة‬\n‫تتضمــن إيضاح ـ ًا لدعــواه‪ ،‬واملدعــى عليــه قــدم مذكــرة تتضمــن دفع ـ ًا‬\n‫موضوعي ـ ًا للدعــوى حســبما قــال‪ ،‬فأفهمتهمــا بأنــه ال مبــرر لتقــدمي‬\n‫هــذه املذكــرات حيــث لــم يوجــد أثنــاء املرافعــة الســابقة مــا يســتدعي‬\n‫تقدميهمــا ألي مذكــرة‪ ،‬فأصــرا علــى طلبهمــا‪ ،‬وبعــد االطــاع علــى‬\n\n\n                                                                                       ‫‪298‬‬\n\f      ‫املذكرتــن قــررت رد طلبهمــا وعــدم ضبــط املذكرتــن وحفظـ ًا للواقــع‬\n      ‫ســيتم إرفــاق املذكرتــن باملعاملــة‪ ،‬ويف جلســة أخــرى حضر الطرفان ‪،‬‬\n      ‫ـاء مــا تقــدم مــن الدعــوى واإلجابــة وبعــد‬\n                                                    ‫ثــم جــرى قفــل بــاب املرافعــة فبنـ ً‬\n      ‫االطــاع علــى املــواد ذات الصلــة مــن نظــام احملامــاة والئحتــه التنفيذيــة‬\n      ‫واســتناد ًا للمــادة ‪ 83‬مــن نظــام املرافعــات الشــرعية وألن احلكــم يف‬\n      ‫ـوكل فيهــا‬  ‫هــذه القضيــة فــرع عــن احلكــم يف القضيــة األصليــة التــي تـ ّ‬\n      ‫املدعــي فقــد قــررت التوقــف عــن نظــر القضيــة إلــى حــن انتهــاء القضيــة‬\n      ‫األصليــة املنظــورة لــدي بشــأن تركــة ‪ ، ...‬وبعــرض ذلــك علــى الطرفــن‬\n      ‫قــرر املدعــى عليــه وكالــة القناعــة ولــم يقنــع املدعــي وكالــة وطلــب رفــع‬\n      ‫املعاملــة حملكمــة االســتئناف واســتعد بتقــدمي الئحــة اعتراضيــة فأجيــب‬\n      ‫لطلبــه وجــرى تســليمه نســخة مــن احلكــم لتقــدمي مــا لديــه مــن اعتــراض‬\n      ‫وأفهــم بتعليمــات التمييــز وأن عليــه تقــدمي اعتراضــه يف مــدة أقصاهــا‬\n      ‫ثالثــون يوم ـ ًا مــن اســتالمه للحكــم وإال ســقط حقــه يف االعتــراض‬\n      ‫ففهــم ذلــك واســتعد بــه وبــاهلل التوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                    ‫وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/07/22‬ه ـ‬\n      ‫احلمــد هلل وحــده أمــا بعــد فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n      ‫املقيــدة لــدى احملكمــة برقــم ‪ 342233374‬وتاريــخ ‪ 1434/9/22‬ه ـ‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة القطيــف برقــم‬\n      ‫‪ 332158039‬وتاريــخ ‪1434/ 9/15‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ‪......... /‬املســجل برقــم ‪.........‬وتاريــخ‬\n      ‫‪1434/7/25‬ه ـ بشــأن دعــوى‪......... /‬ضــد‪......... /‬يف قضيــة حقوقيــة‬\n      ‫وقــد تضمــن الصــك حكــم فضيلــة القاضــي مبــا هــو مــدون ومفصــل‬\n\n\n‫‪299‬‬\n\f‫فيــه ‪ .‬وبدراســةالصك وصــورة ضبطــه والالئحتــن االعتراضيتــن‬\n‫وأوراق املعاملــة قررنــا املصادقــة علــى مــا أجــراه فضيلــة القاضــي واهلل‬\n‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‬\n                                                         ‫‪1434/12/23‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                 ‫‪300‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":294,"source_page_end":300,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1ce6d28a0c3776e4c66be20b07effd7ee0c255d91735798d96eed733e7d15ece","normalized_text_hash":"3296da822d8e2116d2cf1c86f5ca767932c79861437739b94da33d3bf0998904","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p294-34279057"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

